/* surgery-data.js — entries of the Surgery Atlas (surgery-atlas.html).
 * Patient-leaflet level: why an operation is done, the main steps, recovery,
 * risks and its history. For learning — not medical advice. */
(function () {
  const B = (org, tool, cut) => ['body', { org, tool: tool || 'scalpel', cut: cut || 'open' }];
  window.SURGERY_CATS = {
    milestone: ['Milestones & methods', '#8a6a4a', '📜'],
    brain: ['Brain, spine & nerves', '#8a6cc0', '🧠'],
    eye: ['Eyes', '#2a8fa3', '👁️'],
    ent: ['Ear, nose, throat & neck', '#c9922a', '👂'],
    heart: ['Heart & blood vessels', '#c0392b', '❤️'],
    chest: ['Lungs, chest & breast', '#d9534f', '🫁'],
    gut: ['Stomach, liver & bowel', '#a0522d', '🍽️'],
    kidney: ['Kidneys, bladder & prostate', '#b8860b', '💧'],
    women: ['Pregnancy, birth & women’s health', '#c2185b', '🤰'],
    bone: ['Bones & joints', '#4f7598', '🦴'],
    transplant: ['Transplants', '#2e7d32', '🔁'],
    plastic: ['Plastic & reconstructive', '#e67e22', '✨'],
    emergency: ['Emergency & trauma', '#b71c1c', '🚑'],
    tech: ['New technology', '#3e8ec4', '🤖']
  };
  window.SURGERY_ERAS = [
    { n: 'Ancient surgery', to: 500, range: 'before 500 CE', intro: 'Surgeons in Egypt, India, Greece, Rome, China and the Americas set bones, drained wounds, removed stones and even drilled into the skull — all without anaesthesia or knowledge of germs.' },
    { n: 'Medieval & early modern', to: 1800, range: '500 – 1800', intro: 'Surgeons of the Islamic world wrote great textbooks; in Europe, barber-surgeons and military surgeons learned on the battlefield. Speed mattered, because there was no pain relief.' },
    { n: 'Anaesthesia & antisepsis', to: 1900, range: '1800 – 1900', intro: 'Ether and chloroform ended the pain of surgery in the 1840s, and Lister’s antiseptic methods in the 1860s stopped many deadly infections. Surgeons could finally operate slowly and carefully inside the body.' },
    { n: 'Modern surgery is born', to: 1946, range: '1900 – 1945', intro: 'Blood transfusion, X-rays, sterile gloves and masks, and the lessons of two world wars made surgery far safer. Penicillin arrived in the 1940s.' },
    { n: 'Hearts, transplants & implants', to: 1980, range: '1946 – 1979', intro: 'The heart-lung machine allowed open-heart surgery. Kidneys, livers and hearts were transplanted, and artificial hips, lenses and pacemakers went inside the body.' },
    { n: 'Keyhole & high-tech surgery', to: 99999, range: '1980 – today', intro: 'Small cameras let surgeons operate through tiny cuts. Robots, lasers, 3D printing, scans and safety checklists made operations shorter, safer and easier to recover from.' }
  ];
  window.SURGERIES = [
    // ---------------- milestones & methods
    { id: 'trepanation', n: 'Trepanation (skull drilling)', c: 'milestone', y: -5000, d: 'by c. 5000 BCE', r: 'Europe (Ensisheim, France), later worldwide', w: 'Neolithic healers; later Inca surgeons', s: 'Cutting or scraping a hole in the skull — the oldest known surgery. Many patients survived: the bone around the hole healed.', why: 'Possibly to treat head injuries, headaches, seizures or to release “spirits”. Today a similar burr hole drains blood pressing on the brain.', steps: ['Hair was cut and the scalp opened.', 'The bone was scraped, cut or drilled with stone or metal tools.', 'A disc of bone was lifted out.', 'The wound was covered; healed edges on old skulls show many people lived for years.'], then: 'Found on skulls from Europe, Africa, Asia and the Americas. Inca surgeons in Peru had survival rates of over 70%.', f: 'Some people wore the removed disc of bone as a charm.', p: ['skull'], x: ['brain-tumour', ['body-map.html', 'The brain in Body Map']] },
    { id: 'edwin-smith', n: 'Edwin Smith Papyrus', c: 'milestone', y: -1600, d: 'c. 1600 BCE (copy of older texts)', r: 'Ancient Egypt', w: 'Egyptian physicians (once linked to Imhotep)', s: 'The oldest known surgical textbook: 48 cases of injuries to the head, neck, spine and chest, with examination and treatment.', why: 'It treats injuries with careful observation rather than magic — an early scientific approach.', then: 'It describes stitching wounds, setting broken jaws and using honey (which kills germs) on wounds.', f: 'It contains the first known written description of the brain.', p: ['med', { i: 'book' }], x: ['sushruta-samhita', 'hippocratic-surgery'] },
    { id: 'sushruta-samhita', n: 'Sushruta Samhita', c: 'milestone', y: -600, d: 'c. 6th century BCE (dates debated)', r: 'Ancient India (Varanasi)', w: 'Sushruta', s: 'A great Sanskrit book of medicine and surgery describing over 300 operations and 120 instruments.', why: 'It taught surgeons to practise on fruit, leather and dead animals before operating on people.', then: 'It describes nose reconstruction, cataract couching, removing bladder stones and treating fractures.', f: 'Sushruta is often called the “father of surgery” in India.', p: ['instruments'], x: ['rhinoplasty-sushruta', 'cataract-couching', 'lithotomy'] },
    { id: 'hippocratic-surgery', n: 'Hippocratic and Greek surgery', c: 'milestone', y: -400, d: 'c. 400 BCE', r: 'Ancient Greece (Kos)', w: 'Hippocrates and his followers', s: 'Greek doctors wrote books on setting fractures, putting back dislocated joints and treating head wounds.', why: 'They taught that disease has natural causes and that doctors should observe patients carefully.', then: 'The Hippocratic bench was a frame that stretched broken limbs to line the bones up.', f: 'The Hippocratic Oath says “I will not cut for stone” — leaving bladder-stone surgery to specialists.', p: ['med', { i: 'book' }], x: ['galen', 'lithotomy'] },
    { id: 'galen', n: 'Galen of Pergamon', c: 'milestone', y: 160, d: 'c. 160 CE', r: 'Roman Empire', w: 'Galen', s: 'A Greek doctor who learned by treating wounded gladiators and dissecting animals. His books ruled medicine for 1,400 years.', why: 'He showed that arteries carry blood and that nerves from the brain control the voice.', then: 'Because human dissection was banned, some of his anatomy (based on animals) was wrong — Vesalius corrected it in 1543.', f: 'He called gladiators’ wounds “windows into the body”.', p: ['med', { i: 'book' }], x: ['al-zahrawi', ['medicine-atlas.html#vesalius', 'Vesalius in the Medicine Atlas']] },
    { id: 'hua-tuo', n: 'Hua Tuo and early anaesthesia', c: 'milestone', y: 200, d: 'c. 200 CE', r: 'China', w: 'Hua Tuo', s: 'A Chinese surgeon said to have used a herbal drink, mafeisan, to make patients unconscious before abdominal surgery.', why: 'If true, it would be the first general anaesthetic — 1,600 years before ether.', then: 'The recipe was lost; historians are unsure what it contained (perhaps cannabis or datura).', f: 'Legend says he offered to operate on the warlord Cao Cao’s head, who suspected a plot and had him executed.', p: ['med', { i: 'herb', flower: 1, color: '#e2a63b' }], x: ['ether'] },
    { id: 'al-zahrawi', n: 'Al-Zahrawi’s Kitab al-Tasrif', c: 'milestone', y: 1000, d: 'c. 1000', r: 'Córdoba, al-Andalus (Spain)', w: 'Abu al-Qasim al-Zahrawi (Albucasis)', s: 'A 30-volume medical encyclopaedia whose surgery volume drew over 200 instruments, many designed by Al-Zahrawi himself.', why: 'Translated into Latin, it was a key surgery textbook in Europe for 500 years.', then: 'He described tying blood vessels, using catgut for stitches, and treating fractures and dental problems.', f: 'He is believed to be the first to use catgut (made from animal gut) for internal stitches.', p: ['instruments'], x: ['galen', 'pare-ligature'] },
    { id: 'barber-surgeons', n: 'Barber-surgeons', c: 'milestone', y: 1540, d: '1540 (London company)', r: 'Europe', w: 'Guilds of barbers and surgeons', s: 'For centuries surgery was a craft, often done by barbers who also cut hair, pulled teeth and let blood.', why: 'Surgeons learned by apprenticeship. In London the Company of Barber-Surgeons was formed in 1540; they split in 1745.', then: 'University-trained physicians looked down on surgeons as craftsmen.', f: 'The red and white barber’s pole is said to stand for blood and bandages.', p: ['e', '💈'], x: ['pare-ligature', 'amputation'] },
    { id: 'pare-ligature', n: 'Paré’s ligatures and gentle wound care', c: 'milestone', y: 1545, d: '1545', r: 'France', w: 'Ambroise Paré', s: 'A French army barber-surgeon who stopped pouring boiling oil on gunshot wounds and tied off bleeding vessels with thread instead of burning them.', why: 'His gentler methods caused less pain and helped more soldiers survive.', then: 'In 1537 he ran out of oil and used a soothing ointment instead — and found those patients did better.', f: 'He wrote: “I dressed him, God healed him.”', p: ['instruments'], x: ['amputation', 'al-zahrawi'] },
    { id: 'ether', n: 'Ether anaesthesia', c: 'milestone', y: 1846, d: '16 October 1846', r: 'Boston, USA', w: 'William T. G. Morton (also Crawford Long, 1842)', s: 'The first public operation under ether, at Massachusetts General Hospital, showed that surgery could be painless.', why: 'Before anaesthesia, surgeons had to be fast and patients were held down. Now operations could be slow and careful.', then: 'Within months ether was used worldwide; chloroform followed in 1847 (James Young Simpson).', f: 'The surgeon John Collins Warren said: “Gentlemen, this is no humbug.” The room is still called the Ether Dome.', p: ['body', { org: 'face', tool: 'ether', cut: 'none' }], x: ['chloroform', 'hua-tuo', 'local-anaesthesia'] },
    { id: 'chloroform', n: 'Chloroform', c: 'milestone', y: 1847, d: '1847', r: 'Edinburgh, Scotland', w: 'James Young Simpson', s: 'A sweet-smelling anaesthetic, easier to use than ether, made famous when Queen Victoria used it in childbirth.', why: 'It made pain relief in childbirth acceptable.', then: 'Chloroform could stop the heart, so it was later replaced by safer drugs.', f: 'Simpson and friends tested chemicals on themselves after dinner and woke up under the table.', p: ['body', { org: 'face', tool: 'ether', cut: 'none' }], x: ['ether', 'caesarean'] },
    { id: 'antisepsis', n: 'Antiseptic surgery', c: 'milestone', y: 1867, d: '1867', r: 'Glasgow, Scotland', w: 'Joseph Lister', s: 'Lister used carbolic acid to kill germs on wounds, hands and instruments, and deaths after surgery fell sharply.', why: 'Before this, about half of patients after major surgery died of infection.', then: 'Lister was inspired by Louis Pasteur’s germ theory. His wards became far safer.', f: 'The mouthwash Listerine is named after him.', p: ['med', { i: 'bacteria', color: '#4e9e73' }], x: ['aseptic-surgery', ['medicine-atlas.html#germ-theory', 'Germ theory']] },
    { id: 'local-anaesthesia', n: 'Local anaesthesia', c: 'milestone', y: 1884, d: '1884', r: 'Vienna, Austria', w: 'Carl Koller', s: 'Numbing only part of the body — first with cocaine drops in the eye — so patients can stay awake.', why: 'Many operations no longer need general anaesthesia, which is safer for patients.', then: 'Cocaine was replaced by safer drugs such as procaine (1905) and lidocaine (1943). Spinal anaesthesia came in 1898.', f: 'Koller showed it worked by numbing a frog’s eye.', p: ['med', { i: 'syringe', color: '#6fa8c9' }], x: ['ether', 'cataract-surgery'] },
    { id: 'aseptic-surgery', n: 'Aseptic surgery: gloves, gowns and masks', c: 'milestone', y: 1890, d: '1890s', r: 'Germany and USA', w: 'William Halsted, Ernst von Bergmann, Jan Mikulicz', s: 'Instead of killing germs in the wound, keep germs out: sterilised instruments, gowns, rubber gloves and masks.', why: 'It made the operating room a germ-free zone, the way it is today.', then: 'Steam sterilisers (autoclaves) cleaned instruments; masks came in 1897.', f: 'Halsted had rubber gloves made for his nurse Caroline Hampton, whose hands hurt from the chemicals — he later married her.', p: ['body', { org: 'hand', tool: 'gloves', cut: 'none' }], x: ['antisepsis', 'surgical-checklist'] },
    { id: 'x-rays', n: 'X-rays in surgery', c: 'milestone', y: 1895, d: '1895', r: 'Würzburg, Germany', w: 'Wilhelm Röntgen', s: 'Rays that pass through flesh but not bone let surgeons see broken bones and bullets inside the body for the first time.', why: 'Diagnosis before surgery became far more accurate.', then: 'Within a year, X-rays were used to find bullets in soldiers.', f: 'The first X-ray picture of a person was Röntgen’s wife’s hand, with her ring.', p: ['med', { i: 'xray' }], x: ['plaster-cast', ['medicine-atlas.html#x-rays', 'X-rays in the Medicine Atlas']] },
    { id: 'blood-transfusion', n: 'Blood groups and transfusion', c: 'milestone', y: 1901, d: '1901', r: 'Vienna, Austria', w: 'Karl Landsteiner', s: 'Landsteiner discovered the A, B and O blood groups, which explained why many early transfusions killed people.', why: 'Matching blood made transfusion safe, allowing big operations and saving the injured.', then: 'Stored blood was used in WWI (1917); the first blood bank opened in Chicago in 1937.', f: 'Landsteiner won the Nobel Prize in 1930. World Blood Donor Day is on his birthday, 14 June.', p: ['med', { i: 'blood' }], x: ['heart-lung-machine', 'triage'] },
    { id: 'electrosurgery', n: 'Electrosurgery', c: 'tech', y: 1926, d: '1926', r: 'Boston, USA', w: 'William Bovie and Harvey Cushing', s: 'A pen-like tool that cuts and seals blood vessels with high-frequency electric current.', why: 'Less bleeding means clearer views and safer operations, especially in the brain.', steps: ['A pad is stuck on the patient’s skin to complete the circuit.', 'The surgeon uses the pen to cut or to seal small vessels.', 'Smoke is sucked away.'], then: 'Cushing used it to remove brain tumours he had thought impossible to operate on.', f: 'Surgeons still call it “the Bovie”.', p: ['body', { org: 'brain', tool: 'needle', cut: 'open' }], x: ['brain-tumour'] },
    { id: 'surgical-checklist', n: 'Surgical safety checklist', c: 'milestone', y: 2008, d: '2008', r: 'World Health Organization', w: 'Atul Gawande and the WHO', s: 'A one-page list checked aloud before, during and after surgery: right patient, right operation, right side, allergies, instruments counted.', why: 'In trials it cut deaths and complications by about a third.', then: 'Inspired by checklists used by airline pilots.', f: 'It takes about two minutes to complete.', p: ['med', { i: 'book' }], x: ['aseptic-surgery'] },
    // ---------------- emergency
    { id: 'triage', n: 'Triage and field ambulances', c: 'emergency', y: 1792, d: '1792', r: 'France', w: 'Dominique-Jean Larrey', s: 'Sorting the wounded by how urgently they need care, and carrying them quickly to surgeons in light “flying ambulances”.', why: 'Treating the most urgent first, whatever their rank, saves the most lives.', steps: ['Check breathing, bleeding and consciousness.', 'Sort each patient into a group (for example: immediate, delayed, minor).', 'Treat and move the most urgent first.', 'Re-check everyone often.'], then: 'Larrey was Napoleon’s chief surgeon. Today’s emergency departments still triage everyone.', f: 'Larrey once did about 200 amputations in 24 hours at the Battle of Borodino (1812).', p: ['med', { i: 'cross', color: '#c0392b' }], x: ['tourniquet', 'trauma-centre', ['weapons-atlas.html#military-helicopter', 'Helicopters in the Weapons Atlas']] },
    { id: 'tourniquet', n: 'Tourniquet', c: 'emergency', y: 1718, d: '1718', r: 'France', w: 'Jean-Louis Petit', s: 'A tight band around a limb that stops severe bleeding by squeezing the artery shut.', why: 'Heavy bleeding from a limb can kill in minutes.', steps: ['Place the band a few centimetres above the wound, not on a joint.', 'Tighten until the bleeding stops.', 'Note the time it was put on.', 'Leave it on until a medical team takes over.'], rec: 'Modern tourniquets can safely stay on for about two hours.', risk: 'Left on too long it can damage the limb.', then: 'Petit invented a screw tourniquet in 1718. Modern combat tourniquets saved thousands of soldiers in Iraq and Afghanistan.', f: '“Stop the Bleed” courses teach anyone how to use one.', p: B('arm', 'stitch', 'none'), x: ['amputation', 'triage'] },
    { id: 'tracheostomy', n: 'Tracheostomy', c: 'emergency', y: 1546, d: '1546 (first well-documented success)', r: 'Italy', w: 'Antonio Musa Brasavola', s: 'A small opening in the front of the neck into the windpipe, so air can bypass a blocked throat.', why: 'For blocked airways, long-term breathing machines or after head and neck surgery.', steps: ['The patient is given anaesthesia (or local numbing in an emergency).', 'A small cut is made below the voice box.', 'A hole is made in the windpipe and a tube placed in it.', 'The tube is secured with ties and connected to oxygen if needed.'], rec: 'Many tubes are removed once breathing is normal; the hole heals in days to weeks.', risk: 'Bleeding, infection, the tube blocking or coming out.', then: 'Described in ancient Egypt and India. In 1546 Brasavola saved a patient with a throat abscess.', f: 'George Washington’s doctors debated a tracheostomy in 1799 but did not do it.', p: B('neck', 'scalpel', 'open'), x: ['tonsillectomy', 'laryngectomy'] },
    { id: 'chest-drain', n: 'Chest drain', c: 'emergency', y: 1875, d: '1875', r: 'Germany', w: 'Gotthard Bülau', s: 'A tube placed between the ribs to let out air, blood or fluid that is squashing a lung.', why: 'A collapsed lung (pneumothorax) or blood in the chest after injury.', steps: ['The skin is numbed.', 'A small cut is made between two ribs on the side of the chest.', 'A tube is pushed into the space around the lung.', 'It is connected to a bottle with water that lets air out but not in.'], rec: 'The drain usually stays for a few days until the lung re-expands.', risk: 'Pain, infection, bleeding, damage to nearby organs.', then: 'Bülau’s water seal is still the basic idea used today.', f: 'The bubbles in the water bottle show air leaking from the lung.', p: B('lungs', 'catheter', 'open'), x: ['pneumonectomy', 'triage'] },
    { id: 'wound-debridement', n: 'Wound cleaning (debridement)', c: 'emergency', y: 1915, d: '1915', r: 'France (WWI)', w: 'Alexis Carrel and Henry Dakin', s: 'Cutting away dead and dirty tissue from a wound, then washing it, so infection cannot spread.', why: 'Battlefield wounds full of mud killed by gas gangrene and infection before antibiotics.', steps: ['The wound is cleaned and numbed or the patient is anaesthetised.', 'Dead, damaged or dirty tissue is cut away.', 'The wound is washed thoroughly.', 'It may be left open and closed a few days later when clean.'], rec: 'Depends on the wound; dressings are changed regularly.', risk: 'Bleeding, infection, slow healing.', then: 'Carrel and Dakin washed wounds constantly with a mild bleach solution, cutting deaths from infection.', f: 'Carrel also won a Nobel Prize for joining blood vessels.', p: ['med', { i: 'bandage' }], x: ['antisepsis', 'skin-graft'] },
    { id: 'trauma-centre', n: 'Trauma centres and the “golden hour”', c: 'emergency', y: 1961, d: '1961', r: 'Baltimore, USA', w: 'R Adams Cowley', s: 'Hospitals ready day and night to treat badly injured people at once, with a full team waiting.', why: 'Cowley showed that getting badly injured people to surgery within about an hour greatly improved survival.', steps: ['Paramedics alert the trauma team before arrival.', 'The team checks airway, breathing, circulation and bleeding at once.', 'Scans find the injuries.', 'Patients go straight to surgery if needed.'], then: 'Cowley’s Shock Trauma Center in Baltimore was a model for trauma systems worldwide.', f: 'Helicopter ambulances were part of the plan from the start.', p: ['med', { i: 'hospital' }], x: ['triage', 'damage-control'] },
    { id: 'damage-control', n: 'Damage control surgery', c: 'emergency', y: 1993, d: '1993', r: 'Philadelphia, USA', w: 'Michael Rotondo and William Schwab', s: 'For a dying patient, a short operation to stop bleeding and leaks only — the full repair comes days later.', why: 'Very sick patients become cold, their blood stops clotting and long operations can kill them.', steps: ['Stop the bleeding and contamination quickly.', 'Leave the belly temporarily closed or covered.', 'Warm and stabilise the patient in intensive care.', 'Return to theatre for full repair when stable.'], then: 'The idea came from Navy ships: keep the ship afloat first, repair it later.', f: 'It is now standard in military and civilian trauma care.', p: B('belly', 'stitch', 'open'), x: ['trauma-centre'] },
    { id: 'amputation', n: 'Amputation', c: 'bone', y: 1545, d: 'Ancient; ligatures from 1545', r: 'Worldwide', w: 'Ambroise Paré; later Robert Liston and others', s: 'Removing part of a limb to save a life — after severe injury, infection, poor blood supply or cancer.', why: 'When a limb cannot be saved, removing it can stop infection or bleeding.', steps: ['The patient is anaesthetised.', 'Skin and muscle flaps are planned to cover the end.', 'Blood vessels are tied off and nerves cut cleanly.', 'Bone is cut and smoothed; flaps are stitched over it.'], rec: 'Weeks of healing, then rehabilitation and often a prosthesis.', risk: 'Infection, phantom limb pain, wound problems.', then: 'Before anaesthesia, speed was everything: Robert Liston could amputate a leg in under three minutes in the 1840s.', f: 'Modern prosthetic limbs can be controlled by signals from the muscles.', p: B('leg', 'saw', 'open'), x: ['tourniquet', 'pare-ligature', 'replantation'] },
    // ---------------- brain
    { id: 'brain-tumour', n: 'Brain tumour removal (craniotomy)', c: 'brain', y: 1884, d: '1884', r: 'London, UK', w: 'Rickman Godlee; later Harvey Cushing', s: 'Opening the skull to remove a tumour from the brain, then putting the bone back.', why: 'To remove tumours that press on the brain and cause seizures, weakness or headaches.', steps: ['Scans map the tumour; the patient is anaesthetised (or kept awake for some tumours).', 'A piece of skull is removed.', 'Using a microscope, the surgeon removes as much tumour as safely possible.', 'The bone is fixed back with small plates.'], rec: 'Usually a few days in hospital; full recovery takes weeks.', risk: 'Bleeding, infection, seizures, weakness or speech problems depending on the area.', then: 'Godlee removed a tumour in 1884 after it was located from the patient’s symptoms alone. Cushing reduced deaths from about 90% to under 10%.', f: 'Cushing kept careful records of over 2,000 brain tumours.', p: B('brain', 'microscope', 'open'), x: ['trepanation', 'awake-brain-surgery', 'gamma-knife'] },
    { id: 'awake-brain-surgery', n: 'Epilepsy surgery and awake brain mapping', c: 'brain', y: 1886, d: '1886', r: 'London, then Montreal', w: 'Victor Horsley; Wilder Penfield (1930s)', s: 'Removing the small area of brain that starts seizures. The patient may be awake so surgeons can test speech and movement.', why: 'For epilepsy that medicines cannot control.', steps: ['Tests and scans find where the seizures start.', 'The skull is opened under anaesthesia; the patient may be woken up.', 'The brain is gently stimulated to map speech and movement areas.', 'The seizure area is removed, avoiding the mapped areas.'], rec: 'Most people leave hospital in about a week.', risk: 'Weakness, memory or speech problems, infection.', then: 'Penfield’s maps of the brain led to the famous “homunculus” drawing.', f: 'The brain feels no pain, so awake surgery is possible with numbing of the scalp.', p: B('brain', 'needle', 'open'), x: ['brain-tumour', 'deep-brain-stimulation'] },
    { id: 'lobotomy', n: 'Lobotomy (abandoned)', c: 'brain', y: 1935, d: '1935', r: 'Portugal, then USA', w: 'António Egas Moniz; Walter Freeman', s: 'An operation that cut connections in the front of the brain to treat mental illness. It caused great harm and was abandoned.', why: 'It was a desperate attempt to treat severe mental illness before effective medicines existed.', then: 'About 40,000 people had it in the USA. Many were left with lasting damage. Moniz won a Nobel Prize in 1949, which is still controversial.', f: 'It fell out of use after the first antipsychotic drugs arrived in the 1950s — a warning about using surgery without good evidence.', p: B('brain', 'needle', 'none'), x: ['deep-brain-stimulation'] },
    { id: 'aneurysm-clipping', n: 'Brain aneurysm repair', c: 'brain', y: 1937, d: '1937', r: 'Baltimore, USA', w: 'Walter Dandy; coiling by Guido Guglielmi (1991)', s: 'Sealing off a weak, bulging blood vessel in the brain before it bursts.', why: 'A burst aneurysm causes a dangerous bleed.', steps: ['Clipping: the skull is opened and a tiny metal clip closes the neck of the bulge.', 'Coiling: a thin tube is passed from the groin up to the brain.', 'Soft platinum coils are pushed into the bulge to fill it.', 'Scans check it is sealed.'], rec: 'Coiling: a few days. Clipping: about a week, longer if it had burst.', risk: 'Stroke, bleeding, the aneurysm coming back.', then: 'Dandy put the first clip on an aneurysm in 1937. Coils (1991) avoided opening the skull.', f: 'Guglielmi’s coils are released by a tiny electric current.', p: B('brain', 'catheter', 'catheter'), x: ['cardiac-catheter', 'angioplasty'] },
    { id: 'hydrocephalus-shunt', n: 'Shunt for hydrocephalus', c: 'brain', y: 1949, d: '1949', r: 'USA', w: 'Frank Nulsen and Eugene Spitz; John Holter (valve, 1956)', s: 'A thin tube with a valve that drains extra fluid from the brain to the belly.', why: 'Too much fluid in the brain (hydrocephalus) presses on it.', steps: ['A small hole is made in the skull.', 'A tube is put into the fluid space in the brain.', 'It runs under the skin to the belly.', 'A valve controls how much fluid drains.'], rec: 'A few days in hospital.', risk: 'Blockage, infection, needing replacement over time.', then: 'Engineer John Holter designed his valve for his son Casey in 1956.', f: 'Many shunt valves can be adjusted with a magnet from outside the head.', p: B('brain', 'catheter', 'open'), x: ['brain-tumour'] },
    { id: 'discectomy', n: 'Slipped disc surgery (discectomy)', c: 'brain', y: 1934, d: '1934', r: 'Boston, USA', w: 'William Mixter and Joseph Barr', s: 'Removing the part of a spinal disc that bulges out and presses on a nerve.', why: 'For severe leg or arm pain, numbness or weakness from a trapped nerve that does not get better.', steps: ['The patient lies face down under anaesthesia.', 'A small cut is made over the spine.', 'A little bone may be removed to reach the disc.', 'The bulging part is taken out under a microscope.'], rec: 'Most people go home the same or next day.', risk: 'Infection, nerve damage, the disc slipping again.', then: 'Mixter and Barr showed that ruptured discs cause sciatica.', f: 'Many slipped discs get better without surgery in a few weeks.', p: ['spine'], x: ['spinal-fusion'] },
    { id: 'carpal-tunnel', n: 'Carpal tunnel release', c: 'brain', y: 1933, d: '1933', r: 'USA', w: 'James Learmonth', s: 'Cutting a tight band in the wrist to free a squashed nerve.', why: 'Tingling, numbness and weakness in the hand from a trapped median nerve.', steps: ['The hand is numbed.', 'A small cut is made in the palm (or a camera is used).', 'The ligament roof of the tunnel is cut.', 'The skin is stitched.'], rec: 'Light hand use in days; full strength in weeks.', risk: 'Tenderness, infection, rarely nerve injury.', then: 'One of the most common hand operations today.', f: 'It usually takes about 15 minutes.', p: ['hand'], x: ['replantation'] },
    { id: 'deep-brain-stimulation', n: 'Deep brain stimulation', c: 'brain', y: 1987, d: '1987', r: 'Grenoble, France', w: 'Alim-Louis Benabid', s: 'Fine wires in the brain send tiny electric pulses to calm the shaking and stiffness of Parkinson’s disease.', why: 'For Parkinson’s, tremor and some other conditions when medicines are not enough.', steps: ['A frame or scan guides the surgeon to an exact target deep in the brain.', 'Thin electrodes are passed through small holes in the skull.', 'The patient may be awake to test the effect.', 'A battery like a pacemaker is placed under the collarbone.'], rec: 'A few days in hospital; settings are adjusted over weeks.', risk: 'Bleeding, infection, speech or mood changes.', then: 'Over 200,000 people have had it.', f: 'Patients can sometimes switch it off and see their tremor return at once.', p: B('brain', 'needle', 'keyhole'), x: ['awake-brain-surgery', 'pacemaker'] },
    // ---------------- eyes
    { id: 'cataract-couching', n: 'Cataract couching (ancient)', c: 'eye', y: -600, d: 'c. 6th century BCE', r: 'India, then the Middle East and Europe', w: 'Described by Sushruta', s: 'A needle pushed the cloudy lens of the eye backwards out of the line of sight. Vision was blurry but some light returned.', why: 'A cataract is a cloudy lens that makes the world look foggy.', then: 'Still done in some places in the 20th century. Modern cataract surgery replaced it.', f: 'Patients needed thick glasses afterwards because they had no lens.', p: ['eye', { cloudy: 1 }], x: ['cataract-surgery', 'sushruta-samhita'] },
    { id: 'strabismus', n: 'Squint surgery', c: 'eye', y: 1839, d: '1839', r: 'Berlin, Germany', w: 'Johann Dieffenbach', s: 'Moving or tightening the small muscles around the eye so the eyes point the same way.', why: 'A squint (strabismus) can cause double vision or a lazy eye.', steps: ['Usually under general anaesthesia.', 'The thin skin over the eye is opened.', 'An eye muscle is moved back or shortened.', 'It is stitched in its new place.'], rec: 'Red, sore eyes for a week or two.', risk: 'Over- or under-correction, double vision.', then: 'Dieffenbach did the operation on a 7-year-old boy in 1839.', f: 'The eye is never taken out during the operation.', p: ['eye'], x: ['cataract-surgery'] },
    { id: 'glaucoma-surgery', n: 'Glaucoma surgery', c: 'eye', y: 1856, d: '1856', r: 'Berlin, Germany', w: 'Albrecht von Graefe; trabeculectomy by John Cairns (1968)', s: 'Making a new drainage path for fluid in the eye to lower the pressure that damages the optic nerve.', why: 'For glaucoma that eye drops or lasers cannot control.', steps: ['The eye is numbed.', 'A tiny flap is made in the white of the eye.', 'A small opening lets fluid drain under the flap.', 'Stitches control the flow.'], rec: 'Eye drops and check-ups for weeks.', risk: 'Pressure too low or high, infection, cataract.', then: 'Von Graefe’s iridectomy (removing a piece of iris) was the first effective treatment.', f: 'Glaucoma is called “the silent thief of sight” because early stages cause no symptoms.', p: ['eye'], x: ['cataract-surgery'] },
    { id: 'corneal-transplant', n: 'Corneal transplant', c: 'transplant', y: 1905, d: '1905', r: 'Olomouc, Austria-Hungary (Czech Republic)', w: 'Eduard Zirm', s: 'Replacing a damaged clear front window of the eye (cornea) with one from a donor.', why: 'Scarring, swelling or disease that clouds the cornea.', steps: ['The damaged centre of the cornea is cut out.', 'A matching circle of donor cornea is prepared.', 'It is stitched in place with very fine thread.', 'Eye drops prevent rejection.'], rec: 'Vision improves slowly over months.', risk: 'Rejection, infection, astigmatism.', then: 'The first successful human organ-tissue transplant. Zirm’s patient, a farm worker blinded by lime, saw again.', f: 'The cornea has no blood vessels, so it is less likely to be rejected than other organs.', p: ['eye'], x: ['kidney-transplant', 'cataract-surgery'] },
    { id: 'cataract-surgery', n: 'Cataract surgery with lens implant', c: 'eye', y: 1949, d: '1949', r: 'London, UK', w: 'Harold Ridley; phacoemulsification by Charles Kelman (1967)', s: 'The cloudy lens is broken up and removed, and a clear plastic lens is put in its place.', why: 'Cataracts are the leading cause of blindness worldwide.', steps: ['The eye is numbed with drops.', 'A tiny cut is made at the edge of the cornea.', 'Ultrasound breaks up the cloudy lens and it is sucked out.', 'A folded plastic lens is slipped in and unfolds.'], rec: 'Most people see better within days.', risk: 'Infection, swelling, a later haze that is easily treated by laser.', then: 'Ridley got the idea from Spitfire pilots whose eyes held bits of plastic canopy without harm.', f: 'It is one of the most common operations in the world and takes about 15 minutes.', p: ['eye', { mode: 'lens', cloudy: 1 }], x: ['cataract-couching', 'lasik'] },
    { id: 'retina-repair', n: 'Retinal detachment repair and vitrectomy', c: 'eye', y: 1970, d: '1970', r: 'Miami, USA', w: 'Jules Gonin (1920s); Robert Machemer (vitrectomy)', s: 'Reattaching the light-sensing layer at the back of the eye, often by removing the gel inside the eye.', why: 'A detached retina causes sudden loss of vision and is an emergency.', steps: ['Tiny instruments enter through the white of the eye.', 'The jelly inside is removed.', 'The retina is flattened and sealed with laser or freezing.', 'A gas bubble holds it in place while it heals.'], rec: 'Patients may need to keep their head in a certain position for days.', risk: 'Cataract, raised pressure, the retina detaching again.', then: 'Gonin first showed that sealing the tear was the key.', f: 'With a gas bubble in the eye, you must not fly — the bubble expands.', p: ['eye', { mode: 'retina' }], x: ['laser-surgery'] },
    { id: 'lasik', n: 'LASIK laser eye surgery', c: 'eye', y: 1990, d: '1990', r: 'Crete, Greece', w: 'Ioannis Pallikaris', s: 'A laser reshapes the cornea so the eye focuses without glasses.', why: 'To correct short sight, long sight and astigmatism.', steps: ['Numbing drops are put in the eye.', 'A thin flap is made on the cornea.', 'An excimer laser reshapes the tissue underneath in seconds.', 'The flap is laid back down.'], rec: 'Vision usually improves within a day.', risk: 'Dry eyes, glare and halos at night, under- or over-correction.', then: 'The excimer laser was first used to etch microchips.', f: 'The laser removes tissue so precisely it can etch a hair.', p: ['eye', { mode: 'laser' }], x: ['cataract-surgery', 'laser-surgery'] },
    // ---------------- ENT
    { id: 'tonsillectomy', n: 'Tonsillectomy', c: 'ent', y: 50, d: '1st century CE (Celsus); common from the 1900s', r: 'Rome, then worldwide', w: 'Described by Celsus', s: 'Removing the tonsils at the back of the throat.', why: 'For frequent bad throat infections or tonsils so big they block breathing in sleep.', steps: ['General anaesthesia.', 'The mouth is held open.', 'Each tonsil is removed through the mouth.', 'Bleeding is stopped with heat or stitches.'], rec: 'Sore throat for one to two weeks.', risk: 'Bleeding, especially around a week later.', then: 'In the mid-1900s it was done far too often; now it is done only when really needed.', f: 'Ice cream after the operation is a tradition, though soft cool food of any kind helps.', p: B('throat', 'scalpel', 'none'), x: ['grommets'] },
    { id: 'laryngectomy', n: 'Laryngectomy (voice box removal)', c: 'ent', y: 1873, d: '1873', r: 'Vienna, Austria', w: 'Theodor Billroth', s: 'Removing the voice box, usually for cancer. The patient then breathes through an opening in the neck.', why: 'For cancer of the larynx.', steps: ['General anaesthesia.', 'The voice box is removed through the neck.', 'The windpipe is brought out to a permanent opening (stoma).', 'A voice valve may be fitted.'], rec: 'Weeks in hospital and speech therapy to learn a new way of speaking.', risk: 'Infection, leaks, swallowing problems.', then: 'Billroth did the first in 1873; his patient used a simple artificial voice box.', f: 'Voice prostheses let many people speak again by pushing air through a small valve.', p: B('neck', 'scalpel', 'open'), x: ['tracheostomy'] },
    { id: 'thyroidectomy', n: 'Thyroid removal', c: 'ent', y: 1876, d: '1870s', r: 'Bern, Switzerland', w: 'Emil Theodor Kocher', s: 'Removing all or part of the thyroid gland in the neck.', why: 'For goitre, overactive thyroid, nodules or cancer.', steps: ['General anaesthesia.', 'A cut is made in a crease at the front of the neck.', 'The thyroid is removed, protecting the voice nerves and tiny calcium glands.', 'The skin is closed.'], rec: 'Home in a day or two; hormone tablets if the whole gland is removed.', risk: 'Hoarse voice, low calcium, bleeding.', then: 'Kocher cut deaths from about 40% to under 1% and won the Nobel Prize in 1909.', f: 'Goitre was common in mountain areas with little iodine; adding iodine to salt nearly ended it.', p: B('thyroid', 'scalpel', 'open'), x: ['laryngectomy'] },
    { id: 'grommets', n: 'Ear tubes (grommets)', c: 'ent', y: 1954, d: '1954', r: 'USA', w: 'Beverly Armstrong', s: 'Tiny tubes placed in the eardrum to let air in and fluid out of the middle ear.', why: 'For “glue ear” or repeated ear infections, mostly in children.', steps: ['A short general anaesthetic.', 'A tiny cut is made in the eardrum through the ear canal.', 'Fluid is sucked out.', 'The tube is placed in the cut.'], rec: 'Usually home the same day; tubes fall out by themselves in months.', risk: 'Discharge, a small hole that remains.', then: 'One of the most common children’s operations.', f: 'The operation takes about 15 minutes.', p: B('ear', 'scope', 'none'), x: ['cochlear-implant', 'stapedectomy'] },
    { id: 'stapedectomy', n: 'Stapedectomy', c: 'ent', y: 1956, d: '1956', r: 'Memphis, USA', w: 'John Shea Jr.', s: 'Replacing a stuck tiny bone of the middle ear with a little piston to restore hearing.', why: 'For otosclerosis, where the stapes bone stops vibrating.', steps: ['Through the ear canal, the eardrum is lifted.', 'The stuck stapes bone is removed or a hole made in it.', 'A tiny piston is fitted.', 'The eardrum is put back.'], rec: 'Hearing often improves within weeks.', risk: 'Dizziness, taste changes, rarely hearing loss.', then: 'Shea made the first piston from Teflon himself.', f: 'The stapes is the smallest bone in the body — about the size of a grain of rice.', p: B('ear', 'microscope', 'none'), x: ['grommets', 'cochlear-implant'] },
    { id: 'cochlear-implant', n: 'Cochlear implant', c: 'ent', y: 1961, d: '1957–1978', r: 'France, USA and Australia', w: 'André Djourno, William House, Graeme Clark', s: 'An electronic device that gives a sense of sound to people with severe deafness by stimulating the hearing nerve.', why: 'For deafness where hearing aids do not help.', steps: ['A cut is made behind the ear.', 'A small hole is drilled through the bone.', 'A thin electrode is threaded into the cochlea.', 'A receiver is placed under the skin; the outer processor is fitted weeks later.'], rec: 'Learning to hear with an implant takes months of practice.', risk: 'Infection, dizziness, taste changes.', then: 'Clark’s multi-channel implant (1978) let people understand speech.', f: 'Over a million people use cochlear implants.', p: B('ear', 'implant', 'open'), x: ['grommets'] },
    { id: 'sinus-surgery', n: 'Keyhole sinus surgery', c: 'ent', y: 1985, d: '1980s', r: 'Austria', w: 'Walter Messerklinger and Heinz Stammberger', s: 'Using a thin camera through the nose to open blocked sinuses — no outside cut.', why: 'For long-term sinusitis or nasal polyps.', steps: ['General anaesthesia.', 'An endoscope is passed into the nose.', 'Blocked openings are widened and polyps removed.', 'The nose may be packed.'], rec: 'Stuffy nose for a week or two.', risk: 'Bleeding, rarely eye or brain-lining injury.', then: 'Before endoscopes, sinuses were opened through cuts in the face or mouth.', f: 'Navigation systems track instruments on a CT scan in real time.', p: B('nose', 'scope', 'none'), x: ['flexible-endoscope'] },
    // ---------------- heart
    { id: 'heart-wound', n: 'First heart repair', c: 'heart', y: 1896, d: '1896', r: 'Frankfurt, Germany', w: 'Ludwig Rehn', s: 'Rehn stitched a stab wound in the heart of a young gardener — the first successful heart operation.', why: 'Before this, surgeons believed the heart could not be touched.', steps: ['The chest was opened.', 'The sac around the heart was opened and blood removed.', 'The wound in the beating heart was closed with stitches.', 'The chest was closed.'], then: 'The surgeon Theodor Billroth had reportedly said a surgeon who tried it would lose the respect of colleagues.', f: 'Rehn put in three stitches while the heart was beating.', p: ['heart'], x: ['cardiac-catheter', 'heart-lung-machine'] },
    { id: 'cardiac-catheter', n: 'Cardiac catheterisation', c: 'heart', y: 1929, d: '1929', r: 'Eberswalde, Germany', w: 'Werner Forssmann', s: 'Passing a thin tube through a vein or artery into the heart to measure pressure, take X-rays or treat it.', why: 'To diagnose heart disease and guide treatments such as stents.', steps: ['The skin in the wrist or groin is numbed.', 'A thin tube is passed through the blood vessel.', 'It is guided to the heart on X-ray.', 'Dye shows the arteries; pressures are measured.'], rec: 'Usually home the same day.', risk: 'Bleeding at the puncture, rarely heart rhythm problems.', then: 'Forssmann pushed a tube into his own heart and walked to the X-ray room to prove it was safe. He won the Nobel Prize in 1956.', f: 'He had to trick a nurse to get the equipment.', p: ['heart', { stent: 0 }], x: ['angioplasty', 'aneurysm-clipping'] },
    { id: 'pda-ligation', n: 'Closing a heart vessel in babies (PDA)', c: 'heart', y: 1938, d: '1938', r: 'Boston, USA', w: 'Robert Gross', s: 'Tying off a blood vessel near the heart that should close after birth but stays open.', why: 'An open ductus arteriosus overloads the heart and lungs.', steps: ['A cut is made on the left side of the chest.', 'The lung is moved gently aside.', 'The vessel is tied or clipped shut.', 'Today it is often closed with a plug via a catheter.'], rec: 'Most children recover quickly.', risk: 'Bleeding, nerve injury to the voice box.', then: 'Gross operated on a 7-year-old girl while his boss was away, because he had been told not to.', f: 'It was the first successful operation for a heart defect.', p: ['heart'], x: ['blue-baby'] },
    { id: 'blue-baby', n: 'Blue baby operation (Blalock–Taussig shunt)', c: 'heart', y: 1944, d: '1944', r: 'Baltimore, USA', w: 'Alfred Blalock, Helen Taussig and Vivien Thomas', s: 'Joining an artery to the lung artery so more blood gets oxygen in babies with heart defects.', why: 'Babies with tetralogy of Fallot looked blue because their blood lacked oxygen.', steps: ['The chest is opened.', 'An artery from the arm is cut and redirected.', 'It is stitched to the lung artery.', 'More blood flows through the lungs.'], rec: 'Babies often turned pink on the operating table.', risk: 'Today replaced by full repair in most cases.', then: 'Vivien Thomas, a Black laboratory technician, developed the method and stood beside Blalock during the first operation. His role was ignored for decades.', f: 'The 2004 film Something the Lord Made tells Thomas’s story.', p: ['heart', { bypass: 1 }], x: ['pda-ligation', 'heart-lung-machine'] },
    { id: 'hole-in-heart', n: 'Hole-in-the-heart repair', c: 'heart', y: 1952, d: '1952', r: 'Minneapolis, USA', w: 'F. John Lewis and C. Walton Lillehei', s: 'Closing a hole in the wall between two chambers of the heart.', why: 'Holes let blood flow the wrong way and strain the heart and lungs.', steps: ['The heart is stopped with a heart-lung machine (or cooled, in 1952).', 'The heart is opened.', 'The hole is stitched or patched.', 'Today many holes are closed with a device passed through a vein.'], rec: 'Children often go home within a week.', risk: 'Rhythm problems, bleeding.', then: 'Lewis cooled a 5-year-old girl to slow her body, giving him 10 minutes to fix the hole.', f: 'Lillehei later used a parent’s circulation to support a child during surgery (1954).', p: ['heart'], x: ['heart-lung-machine'] },
    { id: 'heart-lung-machine', n: 'Open-heart surgery with a heart-lung machine', c: 'heart', y: 1953, d: '1953', r: 'Philadelphia, USA', w: 'John Gibbon', s: 'A machine takes over pumping blood and adding oxygen so the heart can be stopped and opened safely.', why: 'It made repairing valves, holes and arteries inside the heart possible.', steps: ['Tubes connect large vessels to the machine.', 'The machine pumps blood and adds oxygen.', 'The heart is stopped with a cold solution.', 'After repair, the heart is restarted and the machine turned off.'], rec: 'About a week in hospital after most heart operations.', risk: 'Bleeding, stroke, rhythm problems.', then: 'Gibbon worked on it for 20 years. His first success was 18-year-old Cecelia Bavolek.', f: 'IBM engineers helped Gibbon build the machine.', p: ['heart', { valve: 1 }], x: ['valve-replacement', 'cabg', 'blue-baby'] },
    { id: 'carotid-endarterectomy', n: 'Carotid artery surgery', c: 'heart', y: 1953, d: '1953–1954', r: 'Houston and London', w: 'Michael DeBakey; Felix Eastcott', s: 'Cleaning fatty plaque out of the main artery in the neck to prevent strokes.', why: 'Narrowed carotid arteries can send clots to the brain.', steps: ['The neck is numbed or the patient anaesthetised.', 'The artery is clamped.', 'It is opened and the plaque removed.', 'It is stitched, often with a patch.'], rec: 'Home in a day or two.', risk: 'Stroke, nerve injury, bleeding.', then: 'Eastcott’s 1954 patient had had many mini-strokes; she lived for years afterwards.', f: 'Patients may be kept awake so the team can check they can talk and move.', p: B('neck', 'scalpel', 'open'), x: ['angioplasty'] },
    { id: 'pacemaker', n: 'Pacemaker implant', c: 'heart', y: 1958, d: '1958', r: 'Stockholm, Sweden', w: 'Åke Senning and Rune Elmqvist', s: 'A small battery device under the skin sends electrical pulses to keep the heart beating at a safe rate.', why: 'For a slow or irregular heartbeat that causes fainting or tiredness.', steps: ['The skin below the collarbone is numbed.', 'A wire is passed through a vein into the heart on X-ray.', 'It is connected to the pacemaker.', 'The pacemaker is placed in a pocket under the skin.'], rec: 'Home the same or next day; avoid lifting the arm high for weeks.', risk: 'Infection, wire moving.', then: 'The first patient, Arne Larsson, had 26 pacemakers over his life and lived to 86.', f: 'Modern pacemakers can be checked over the internet from home.', p: ['heart', { pacer: 1 }], x: ['deep-brain-stimulation', 'artificial-heart'] },
    { id: 'valve-replacement', n: 'Heart valve replacement', c: 'heart', y: 1960, d: '1960', r: 'USA', w: 'Albert Starr and Lowell Edwards; Dwight Harken', s: 'Replacing a narrowed or leaking heart valve with a mechanical or tissue valve.', why: 'Bad valves strain the heart and cause breathlessness.', steps: ['Open-heart surgery with a heart-lung machine.', 'The faulty valve is cut out.', 'A new valve is stitched in.', 'The heart is restarted.'], rec: 'About a week in hospital; mechanical valves need blood thinners for life.', risk: 'Bleeding, stroke, infection of the valve.', then: 'The Starr–Edwards valve was a ball in a cage.', f: 'Mechanical valves can be heard ticking.', p: ['heart', { valve: 1 }], x: ['heart-lung-machine', 'tavi'] },
    { id: 'cabg', n: 'Coronary bypass (CABG)', c: 'heart', y: 1964, d: '1960s', r: 'Leningrad and Cleveland', w: 'Vasilii Kolesov (1964); René Favaloro (1967)', s: 'Using a vein from the leg or an artery from the chest to carry blood around blocked heart arteries.', why: 'For severe angina or many blocked arteries.', steps: ['A blood vessel is taken from the leg, arm or chest wall.', 'The chest is opened.', 'One end is stitched below the blockage and the other to the aorta.', 'Blood flows around the blockage.'], rec: 'About a week in hospital; 6–12 weeks to recover.', risk: 'Infection, rhythm problems, stroke.', then: 'Favaloro, from Argentina, made the leg-vein bypass standard.', f: 'Patients talk of a “triple” or “quadruple” bypass — the number of grafts.', p: ['heart', { bypass: 1 }], x: ['angioplasty', 'heart-lung-machine'] },
    { id: 'aortic-aneurysm', n: 'Aortic aneurysm repair', c: 'heart', y: 1951, d: '1951', r: 'Paris, France', w: 'Charles Dubost; stent graft by Juan Parodi (1990)', s: 'Replacing or lining a ballooning section of the main artery before it bursts.', why: 'A burst aortic aneurysm is usually fatal.', steps: ['Open repair: the belly is opened and the bulge replaced with a fabric tube.', 'Keyhole repair: a stent graft is passed up from the groin arteries.', 'It is opened inside the bulge to line it.', 'Scans check it is sealed.'], rec: 'Open: about a week. Stent graft: a few days.', risk: 'Bleeding, kidney problems, leaks around the graft.', then: 'Albert Einstein died of a burst aortic aneurysm in 1955 after refusing surgery.', f: 'Many countries screen older men with a quick ultrasound scan.', p: B('belly', 'catheter', 'catheter'), x: ['angioplasty'] },
    { id: 'varicose-veins', n: 'Varicose vein treatment', c: 'heart', y: 1907, d: '1907', r: 'USA', w: 'William Babcock (vein stripping); laser ablation (1999)', s: 'Removing or sealing swollen leg veins.', why: 'For aching, swelling, skin damage or ulcers.', steps: ['Older method: the vein is tied off and pulled out (stripped).', 'Modern method: a thin fibre is passed into the vein.', 'Heat from a laser or radio waves seals it shut.', 'Blood takes other, healthy veins.'], rec: 'Walking the same day; compression stockings for a while.', risk: 'Bruising, numbness, clots.', then: 'Hippocrates described varicose veins about 2,400 years ago.', f: 'Blood simply reroutes through deeper veins.', p: B('vessel', 'laser', 'catheter'), x: ['laser-surgery'] },
    { id: 'angioplasty', n: 'Angioplasty and stents', c: 'heart', y: 1977, d: '1977', r: 'Zurich, Switzerland', w: 'Andreas Grüntzig; stents by Jacques Puel and Ulrich Sigwart (1986)', s: 'A tiny balloon opens a blocked artery from the inside, and a mesh tube (stent) keeps it open.', why: 'For heart attacks and narrowed arteries causing chest pain.', steps: ['A catheter goes in through the wrist or groin.', 'A wire crosses the blockage.', 'A balloon is inflated to squash the plaque.', 'A stent is left in place.'], rec: 'Usually home the next day.', risk: 'Bleeding, the artery narrowing again, rarely heart attack.', then: 'Grüntzig built his first balloon catheters on his kitchen table.', f: 'In a heart attack, opening the artery within 90 minutes saves the most heart muscle.', p: ['heart', { stent: 1 }], x: ['cardiac-catheter', 'cabg', 'tavi'] },
    { id: 'artificial-heart', n: 'Artificial heart', c: 'heart', y: 1982, d: '1982', r: 'Salt Lake City, USA', w: 'Robert Jarvik and William DeVries', s: 'A machine that replaces the heart’s pumping chambers, usually as a bridge to a transplant.', why: 'For people dying of heart failure while waiting for a donor heart.', steps: ['Open-heart surgery with a heart-lung machine.', 'The failing lower chambers are removed (or a pump is added).', 'The device is connected to the blood vessels.', 'Power and control come through a cable or battery pack.'], rec: 'Long hospital stay; careful care of the cable.', risk: 'Clots, stroke, infection.', then: 'Barney Clark lived 112 days with the Jarvik-7. Today most patients get a pump (LVAD) that helps their own heart.', f: 'Some LVAD patients have no pulse because the pump flows continuously.', p: ['heart', { pacer: 1 }], x: ['heart-transplant', 'pacemaker'] },
    { id: 'tavi', n: 'Valve replacement through a catheter (TAVI)', c: 'heart', y: 2002, d: '2002', r: 'Rouen, France', w: 'Alain Cribier', s: 'A new heart valve squeezed onto a catheter is pushed up from the groin and opened inside the old one — no open-heart surgery.', why: 'For a narrowed aortic valve, especially in older people.', steps: ['A catheter goes in through the groin artery.', 'The folded valve is guided to the heart on X-ray.', 'It is expanded inside the old valve.', 'It starts working at once.'], rec: 'Often home in one to three days.', risk: 'Stroke, bleeding, needing a pacemaker.', then: 'Cribier’s first patient had been refused open surgery as too risky.', f: 'Many patients are awake, with only light sedation.', p: ['heart', { valve: 1, stent: 1 }], x: ['valve-replacement', 'angioplasty'] },
    // ---------------- chest
    { id: 'mastectomy', n: 'Breast cancer surgery', c: 'chest', y: 1882, d: '1882', r: 'New York and Baltimore, USA', w: 'William Halsted; breast-conserving surgery by Umberto Veronesi and Bernard Fisher', s: 'Removing breast cancer — either the whole breast (mastectomy) or just the lump with a margin (lumpectomy).', why: 'To remove cancer before it spreads.', steps: ['General anaesthesia.', 'The tumour or breast is removed.', 'A few lymph nodes in the armpit are checked for spread.', 'The breast may be reconstructed at the same time.'], rec: 'Often home within a day; radiotherapy may follow.', risk: 'Infection, arm swelling (lymphoedema), numbness.', then: 'Halsted’s radical mastectomy removed chest muscles too. Trials in the 1970s–80s showed smaller operations work as well for most women.', f: 'The tiny “sentinel” lymph node can be found with a blue dye or a radioactive tracer.', p: B('breast', 'scalpel', 'open'), x: ['breast-implants'] },
    { id: 'pneumonectomy', n: 'Lung removal (pneumonectomy)', c: 'chest', y: 1933, d: '1933', r: 'St Louis, USA', w: 'Evarts Graham', s: 'Removing a whole lung, or part of it (lobectomy), usually for lung cancer.', why: 'To remove lung cancer that has not spread.', steps: ['General anaesthesia with one lung ventilated.', 'The chest is opened between the ribs (or by keyhole).', 'The lung’s artery, vein and airway are divided and sealed.', 'A chest drain is left in.'], rec: 'About a week in hospital; breathing exercises.', risk: 'Air leaks, pneumonia, rhythm problems.', then: 'Graham’s first patient, a doctor, lived 30 more years. Graham, a heavy smoker, later proved smoking causes lung cancer — and died of it.', f: 'People can live a normal life with one lung.', p: ['lung', { tumour: 1 }], x: ['vats', 'chest-drain', ['medicine-atlas.html#smoking-cancer', 'Smoking and cancer']] },
    { id: 'vats', n: 'Keyhole chest surgery (VATS)', c: 'chest', y: 1992, d: '1990s', r: 'Worldwide', w: 'Thoracic surgeons; first thoracoscopy by Hans Christian Jacobaeus (1910)', s: 'Operating on the lungs through small cuts using a camera, without spreading the ribs.', why: 'Less pain and faster recovery than open chest surgery.', steps: ['Three or four small cuts are made between the ribs.', 'A camera shows the inside on a screen.', 'Long instruments remove the tissue.', 'A chest drain is left in.'], rec: 'Often home in a few days.', risk: 'Air leak, bleeding, conversion to open surgery.', then: 'Jacobaeus first looked inside a chest with a scope in 1910.', f: 'Robots are now used for some chest operations too.', p: ['lung', { tumour: 1 }], x: ['pneumonectomy', 'laparoscopy'] },
    // ---------------- gut
    { id: 'appendectomy', n: 'Appendix removal (appendectomy)', c: 'gut', y: 1735, d: '1735 (first recorded)', r: 'London, UK', w: 'Claudius Amyand; Lawson Tait and Charles McBurney (1880s)', s: 'Removing an inflamed appendix, a small finger-like pouch of the bowel.', why: 'Appendicitis can burst and cause a life-threatening infection.', steps: ['General anaesthesia.', 'Usually keyhole: three small cuts and a camera.', 'The appendix is tied off and removed.', 'The cuts are closed.'], rec: 'Home in a day or two; normal activities in two weeks.', risk: 'Infection, bleeding.', then: 'King Edward VII’s coronation was postponed in 1902 so he could have his abscessed appendix drained.', f: 'Some mild appendicitis can be treated with antibiotics alone.', p: B('appendix', 'scope', 'keyhole'), x: ['laparoscopy', 'cholecystectomy'] },
    { id: 'stoma', n: 'Colostomy (stoma)', c: 'gut', y: 1793, d: '1793', r: 'France', w: 'Claude Duret', s: 'Bringing part of the bowel through an opening in the belly so waste goes into a bag.', why: 'After bowel cancer surgery, injury, blockage or inflammatory bowel disease.', steps: ['The bowel is divided.', 'One end is brought through a small opening in the belly wall.', 'It is stitched to the skin.', 'A bag is fitted over it.'], rec: 'Stoma nurses teach care; many stomas are later reversed.', risk: 'Skin irritation, hernia, blockage.', then: 'Duret made a colostomy in a baby born with a blocked bottom; the child lived to 45.', f: 'People with stomas swim, run marathons and travel normally.', p: B('gut', 'stitch', 'open'), x: ['colectomy'] },
    { id: 'gastrectomy', n: 'Stomach removal (gastrectomy)', c: 'gut', y: 1881, d: '1881', r: 'Vienna, Austria', w: 'Theodor Billroth', s: 'Removing part or all of the stomach and joining the rest to the bowel.', why: 'Mainly for stomach cancer; once common for ulcers.', steps: ['General anaesthesia, open or keyhole.', 'The diseased part of the stomach is removed.', 'The remaining stomach (or the gullet) is joined to the small bowel.', 'Lymph nodes are removed for cancer.'], rec: 'Small, frequent meals afterwards; vitamin B12 injections.', risk: 'Leaks, weight loss, “dumping” after meals.', then: 'Billroth’s patient, Therese Heller, lived four months. His joins (Billroth I and II) are still used.', f: 'Ulcer operations became rare after the discovery in 1982 that a bacterium, H. pylori, causes most ulcers.', p: B('stomach', 'scalpel', 'open'), x: ['bariatric', ['medicine-atlas.html#h-pylori', 'H. pylori in the Medicine Atlas']] },
    { id: 'cholecystectomy', n: 'Gallbladder removal', c: 'gut', y: 1882, d: '1882', r: 'Berlin, Germany', w: 'Carl Langenbuch; keyhole by Erich Mühe (1985)', s: 'Removing the gallbladder, a small pouch under the liver that stores bile.', why: 'Gallstones causing pain, infection or pancreatitis.', steps: ['General anaesthesia.', 'Keyhole: the belly is inflated with gas and a camera inserted.', 'The gallbladder’s duct and artery are clipped.', 'It is removed through a small cut near the belly button.'], rec: 'Often home the same day.', risk: 'Bile leak, bile duct injury, bleeding.', then: 'Mühe’s keyhole operation was mocked at first; within a few years it became the standard.', f: 'You can live normally without a gallbladder — bile flows straight from the liver.', p: B('gall', 'scope', 'keyhole'), x: ['laparoscopy', 'appendectomy'] },
    { id: 'hernia-repair', n: 'Hernia repair', c: 'gut', y: 1887, d: '1887', r: 'Padua, Italy', w: 'Edoardo Bassini; mesh by Irving Lichtenstein (1980s)', s: 'Pushing a bulge of bowel or fat back inside and strengthening the weak spot in the belly wall.', why: 'Hernias can hurt and, rarely, trap bowel.', steps: ['Local or general anaesthesia, open or keyhole.', 'The bulge is pushed back.', 'The weak spot is closed.', 'A mesh patch reinforces it.'], rec: 'Home the same day; avoid heavy lifting for a few weeks.', risk: 'Pain, infection, the hernia returning.', then: 'Before Bassini, most hernias came back. Mesh made repairs much stronger.', f: 'Hernia repair is one of the most common operations worldwide.', p: B('pelvis', 'stitch', 'open'), x: ['laparoscopy'] },
    { id: 'whipple', n: 'Whipple operation', c: 'gut', y: 1935, d: '1935', r: 'New York, USA', w: 'Allen Whipple (after Walther Kausch, 1909)', s: 'A big operation to remove the head of the pancreas, part of the bowel, the bile duct and gallbladder.', why: 'Mainly for pancreatic cancer.', steps: ['General anaesthesia; a large or keyhole approach.', 'The head of the pancreas and nearby organs are removed.', 'The pancreas, bile duct and stomach are reconnected to the bowel.', 'Drains are left in.'], rec: 'One to two weeks in hospital.', risk: 'Leaks, infection, diabetes, digestion problems.', then: 'Once very dangerous; in specialist centres deaths are now under 5%.', f: 'It takes about five to seven hours.', p: B('pancreas', 'scalpel', 'open'), x: ['liver-transplant'] },
    { id: 'bariatric', n: 'Weight-loss surgery (gastric bypass)', c: 'gut', y: 1967, d: '1967', r: 'Iowa, USA', w: 'Edward Mason', s: 'Making the stomach smaller and rerouting the bowel to reduce hunger and food intake.', why: 'For severe obesity, especially with diabetes or other health problems.', steps: ['Keyhole surgery under general anaesthesia.', 'A small stomach pouch is made with staples.', 'The small bowel is joined to it, bypassing part.', 'Or a sleeve of stomach is removed instead.'], rec: 'Liquid then soft food for weeks; vitamins for life.', risk: 'Leaks, nutrient deficiencies, gallstones.', then: 'It often puts type 2 diabetes into remission.', f: 'Changes in gut hormones, not just a small stomach, explain much of the effect.', p: B('stomach', 'scope', 'keyhole'), x: ['gastrectomy'] },
    { id: 'colonoscopy', n: 'Colonoscopy and polyp removal', c: 'gut', y: 1969, d: '1969', r: 'New York, USA', w: 'William Wolff and Hiromi Shinya', s: 'A flexible camera looks inside the large bowel and snips off polyps before they turn into cancer.', why: 'For bowel symptoms and cancer screening.', steps: ['The bowel is cleared with a strong laxative the day before.', 'Mild sedation is given.', 'The scope is passed through the bottom.', 'Polyps are removed with a wire loop.'], rec: 'Home the same day.', risk: 'Bleeding, rarely a tear in the bowel.', then: 'Removing polyps this way has prevented countless bowel cancers.', f: 'Shinya invented the wire-loop snare technique.', p: B('gut', 'scope', 'none'), x: ['flexible-endoscope', 'colectomy'] },
    { id: 'colectomy', n: 'Bowel cancer surgery (colectomy)', c: 'gut', y: 1908, d: '1908', r: 'London, UK', w: 'Ernest Miles; total mesorectal excision by Bill Heald (1982)', s: 'Removing the part of the large bowel containing cancer, with its lymph nodes, and joining the ends.', why: 'For bowel cancer and some severe bowel diseases.', steps: ['Keyhole, robotic or open surgery.', 'The section of bowel with its blood supply and lymph nodes is removed.', 'The ends are joined.', 'A temporary stoma may protect the join.'], rec: 'Enhanced recovery programmes get many patients home in days.', risk: 'Leaks, infection, bowel changes.', then: 'Heald’s precise technique for rectal cancer greatly reduced the chance of the cancer coming back.', f: 'Patients are often encouraged to eat and walk the day after surgery.', p: B('gut', 'robot', 'keyhole'), x: ['stoma', 'colonoscopy'] },
    // ---------------- kidney
    { id: 'lithotomy', n: 'Bladder stone removal (lithotomy)', c: 'kidney', y: -400, d: 'Ancient (c. 400 BCE)', r: 'India, Greece and Rome', w: 'Travelling stone-cutters', s: 'Cutting into the bladder to remove a stone — one of the oldest planned operations, done without anaesthesia.', why: 'Bladder stones caused terrible pain.', then: 'In the 1600s–1700s, skilled lithotomists like Frère Jacques Beaulieu travelled Europe. Samuel Pepys celebrated the anniversary of his stone operation every year.', f: 'William Cheselden could do the operation in under a minute in the 1720s.', p: B('bladder', 'scalpel', 'open'), x: ['lithotripsy', 'hippocratic-surgery'] },
    { id: 'nephrectomy', n: 'Kidney removal (nephrectomy)', c: 'kidney', y: 1869, d: '1869', r: 'Heidelberg, Germany', w: 'Gustav Simon', s: 'Removing a kidney, usually for cancer or a kidney that no longer works.', why: 'Kidney cancer, a damaged kidney, or to donate a kidney.', steps: ['Keyhole or robotic surgery under general anaesthesia.', 'The kidney’s artery, vein and ureter are clipped and cut.', 'The kidney is removed through a small cut.', 'Sometimes only the tumour is removed.'], rec: 'Two to four days in hospital.', risk: 'Bleeding, infection, reduced kidney function.', then: 'Simon first proved on dogs that one kidney is enough to live.', f: 'One healthy kidney can do the work of two.', p: B('kidney', 'scope', 'keyhole'), x: ['kidney-transplant'] },
    { id: 'prostatectomy', n: 'Prostate surgery', c: 'kidney', y: 1904, d: '1904', r: 'Baltimore, USA', w: 'Hugh Hampton Young; TURP from 1931', s: 'Removing the prostate for cancer, or trimming it from inside when it blocks the flow of urine.', why: 'Prostate cancer, or an enlarged prostate causing urinary problems.', steps: ['For an enlarged prostate: a scope through the urethra trims tissue (TURP).', 'For cancer: robotic or open surgery removes the whole prostate.', 'The bladder is rejoined to the urethra.', 'A catheter stays in for a while.'], rec: 'TURP: a few days. Removal: a catheter for about a week.', risk: 'Leaking urine, erection problems, bleeding.', then: 'Robotic prostatectomy (2000s) became one of the most common robotic operations.', f: 'Many slow prostate cancers are watched rather than operated on.', p: B('prostate', 'robot', 'keyhole'), x: ['robotic-surgery'] },
    { id: 'vasectomy', n: 'Vasectomy', c: 'kidney', y: 1899, d: '1899', r: 'USA', w: 'Harry Sharp (first in the USA)', s: 'Cutting and sealing the tubes that carry sperm, as permanent contraception.', why: 'For men who do not want more children.', steps: ['Local anaesthetic.', 'A tiny opening is made in the scrotum.', 'Each tube is cut and sealed.', 'Tests weeks later check there is no sperm.'], rec: 'Back to normal in a few days.', risk: 'Bruising, pain, rarely the tubes rejoining.', then: 'Sadly, early vasectomies in the USA were often forced sterilisations; today it must be the patient’s free choice.', f: 'A “no-scalpel” method was developed in China in 1974.', p: B('pelvis', 'scalpel', 'none'), x: ['ivf-retrieval'] },
    { id: 'dialysis-fistula', n: 'Dialysis fistula', c: 'kidney', y: 1966, d: '1966', r: 'New York, USA', w: 'James Cimino and Michael Brescia', s: 'Joining an artery to a vein in the arm so the vein grows big and strong enough for dialysis needles.', why: 'For people with kidney failure who need dialysis several times a week.', steps: ['Local anaesthetic in the arm.', 'An artery and a vein at the wrist or elbow are joined.', 'Over weeks, the vein enlarges.', 'Dialysis needles are then placed in it.'], rec: 'The fistula needs six to eight weeks to mature.', risk: 'Clotting, infection, swelling.', then: 'Before fistulas, repeated tubes wore out patients’ blood vessels.', f: 'You can feel a buzzing “thrill” over a working fistula.', p: B('arm', 'stitch', 'open'), x: ['kidney-transplant', ['medicine-atlas.html#dialysis', 'Dialysis machine']] },
    { id: 'lithotripsy', n: 'Shock-wave lithotripsy', c: 'kidney', y: 1980, d: '1980', r: 'Munich, Germany', w: 'Christian Chaussy (Dornier)', s: 'Breaking kidney stones from outside the body with focused shock waves — no cutting at all.', why: 'Kidney stones that will not pass by themselves.', steps: ['The stone is found on X-ray or ultrasound.', 'A cushion of water is pressed against the side.', 'Thousands of shock waves are focused on the stone.', 'The fragments pass in the urine.'], rec: 'Home the same day.', risk: 'Bruising, pain as fragments pass, needing repeat sessions.', then: 'Engineers at the aircraft maker Dornier noticed shock waves when raindrops hit supersonic planes.', f: 'Lasers through a thin scope are now often used to break stones too.', p: B('kidney', 'xray', 'none'), x: ['lithotomy'] },
    // ---------------- women
    { id: 'ovariotomy', n: 'First abdominal surgery (ovarian cyst)', c: 'women', y: 1809, d: '1809', r: 'Kentucky, USA', w: 'Ephraim McDowell and patient Jane Todd Crawford', s: 'McDowell removed a 10 kg ovarian tumour from Jane Todd Crawford without anaesthesia. She lived another 32 years.', why: 'It proved that opening the abdomen could be survived.', steps: ['Crawford rode 100 km on horseback to reach him.', 'With no anaesthetic, she recited psalms.', 'The tumour was drained and removed in 25 minutes.', 'She was making her bed five days later.'], then: 'Today ovarian cysts are mostly removed by keyhole surgery.', f: 'A crowd outside reportedly threatened to hang McDowell if she died.', p: B('uterus', 'scalpel', 'open'), x: ['hysterectomy', 'ether'] },
    { id: 'fistula-repair', n: 'Childbirth fistula repair', c: 'women', y: 1852, d: '1852', r: 'Alabama, USA (and later worldwide)', w: 'J. Marion Sims (developed on enslaved women)', s: 'Closing a hole between the birth canal and the bladder or bowel caused by a long, blocked labour.', why: 'Fistulas cause constant leaking and isolation; around half a million women still live with them.', steps: ['Anaesthesia.', 'The hole is found and its edges trimmed.', 'Layers are carefully stitched.', 'A catheter rests the bladder while it heals.'], rec: 'About two weeks with a catheter.', risk: 'The repair breaking down.', then: 'Sims developed it by operating many times, without anaesthesia, on enslaved women — Anarcha, Betsey, Lucy and others — who could not consent. Today he is a symbol of how medicine has exploited vulnerable people.', f: 'Hospitals in Ethiopia founded by Drs Catherine and Reginald Hamlin have repaired over 60,000 fistulas.', p: B('pelvis', 'stitch', 'none'), x: ['caesarean'] },
    { id: 'hysterectomy', n: 'Hysterectomy', c: 'women', y: 1843, d: '1840s–1850s', r: 'England and USA', w: 'Charles Clay; Walter Burnham; keyhole by Harry Reich (1989)', s: 'Removing the womb (uterus).', why: 'For fibroids, heavy bleeding, cancer or severe endometriosis.', steps: ['General anaesthesia.', 'Through the vagina, by keyhole or through the belly.', 'The uterus is freed from its blood supply and ligaments.', 'It is removed; the top of the vagina is closed.'], rec: 'Keyhole: home in a day or two; full recovery in about six weeks.', risk: 'Bleeding, infection, injury to bladder or bowel.', then: 'Early operations had very high death rates; anaesthesia and antisepsis changed that.', f: 'Many alternatives now exist, such as removing fibroids alone.', p: B('uterus', 'scope', 'keyhole'), x: ['caesarean', 'laparoscopy'] },
    { id: 'caesarean', n: 'Caesarean section', c: 'women', y: 1882, d: '1882', r: 'Leipzig, Germany', w: 'Max Sänger; earlier James Barry (1826, South Africa)', s: 'Delivering a baby through a cut in the belly and womb.', why: 'When birth through the vagina would be unsafe for mother or baby.', steps: ['Usually a spinal anaesthetic, so the mother is awake.', 'A low cut is made across the belly and then the womb.', 'The baby is lifted out.', 'The womb and belly are stitched in layers.'], rec: 'Two to four days in hospital; about six weeks to heal.', risk: 'Bleeding, infection, clots.', then: 'Mothers rarely survived until Sänger showed in 1882 that the womb must be stitched. James Barry — who lived as a man and was found at death to have been born female — did one of the first where both mother and baby survived.', f: 'Despite the legend, Julius Caesar was probably not born this way — his mother lived for years afterwards.', p: ['pregnant'], x: ['chloroform', 'fetal-surgery', 'fistula-repair'] },
    { id: 'ivf-retrieval', n: 'IVF egg collection', c: 'women', y: 1978, d: '1978', r: 'Oldham, UK', w: 'Patrick Steptoe, Robert Edwards and Jean Purdy', s: 'Collecting eggs from the ovaries so they can be fertilised in a lab and an embryo returned to the womb.', why: 'For infertility.', steps: ['Hormones help several eggs grow.', 'Under sedation, a needle guided by ultrasound collects them.', 'Eggs and sperm are combined in the lab.', 'One embryo is placed in the womb days later.'], rec: 'Home the same day.', risk: 'Ovarian overstimulation, bleeding, infection.', then: 'Louise Brown, born in 1978, was the first IVF baby. Over 12 million babies have since been born by IVF.', f: 'Steptoe first collected eggs by keyhole surgery; ultrasound needles came later.', p: B('uterus', 'needle', 'none'), x: ['uterus-transplant'] },
    { id: 'fetal-surgery', n: 'Surgery on babies before birth', c: 'women', y: 1981, d: '1981', r: 'San Francisco, USA', w: 'Michael Harrison', s: 'Operating on a baby still in the womb to fix problems that would cause serious harm before birth.', why: 'For some cases of spina bifida, a blocked bladder or twin-to-twin transfusion.', steps: ['The mother is anaesthetised.', 'A scope or a small opening in the womb reaches the baby.', 'The problem is repaired.', 'The pregnancy continues.'], rec: 'Close monitoring until birth.', risk: 'Early labour, risks to mother and baby.', then: 'Harrison first drained a baby’s blocked bladder in 1981.', f: 'Laser surgery through a scope can treat twins who share blood vessels in the placenta.', p: ['pregnant'], x: ['caesarean'] },
    // ---------------- bones
    { id: 'plaster-cast', n: 'Plaster cast', c: 'bone', y: 1851, d: '1851', r: 'Netherlands', w: 'Antonius Mathijsen', s: 'Bandages soaked in plaster of Paris harden around a broken limb to hold the bones still while they heal.', why: 'To keep broken bones lined up while they heal.', steps: ['The bones are lined up (sometimes under anaesthesia).', 'Padding is wrapped around the limb.', 'Wet plaster or fibreglass bandages are wrapped over it.', 'It hardens in minutes.'], rec: 'Most casts stay on six to eight weeks.', risk: 'Swelling, stiffness, skin sores.', then: 'Before this, splints of wood, bark or stiffened cloth were used for thousands of years.', f: 'Fibreglass casts are lighter and come in many colours.', p: B('arm', 'xray', 'none'), x: ['fracture-plates', 'x-rays'] },
    { id: 'fracture-plates', n: 'Metal plates, screws and nails', c: 'bone', y: 1895, d: '1890s', r: 'London and Belgium', w: 'William Arbuthnot Lane and Albin Lambotte; nail by Gerhard Küntscher (1939)', s: 'Holding broken bones together from the inside with metal plates, screws or a rod down the middle.', why: 'For fractures that would not heal straight in a cast.', steps: ['General or spinal anaesthesia.', 'The bone ends are lined up.', 'A plate and screws or a rod inside the bone hold them.', 'The wound is closed.'], rec: 'Often walking within days; bone heals in months.', risk: 'Infection, the metal loosening.', then: 'Küntscher’s nails helped German soldiers walk weeks after thigh fractures in WWII. The Swiss AO group (1958) made fixation scientific.', f: 'Many implants are left in for life.', p: B('bone', 'implant', 'open'), x: ['plaster-cast', 'ilizarov'] },
    { id: 'spinal-fusion', n: 'Spinal fusion', c: 'bone', y: 1911, d: '1911', r: 'New York, USA', w: 'Russell Hibbs and Fred Albee', s: 'Joining two or more vertebrae so they grow into one solid bone.', why: 'For some cases of scoliosis, fractures, instability or severe disc disease.', steps: ['General anaesthesia.', 'The spine is reached from the back or front.', 'Screws and rods hold the vertebrae still.', 'Bone graft is added so they fuse.'], rec: 'Several days in hospital; fusion takes months.', risk: 'Nerve injury, infection, the bones not fusing.', then: 'First used to stop tuberculosis damaging the spine.', f: 'The bone used is often from the patient’s own hip or from a bone bank.', p: ['spine', { rods: 1 }], x: ['scoliosis', 'discectomy'] },
    { id: 'acl-reconstruction', n: 'Knee ligament reconstruction (ACL)', c: 'bone', y: 1917, d: '1917', r: 'Bristol, UK', w: 'Ernest Hey Groves', s: 'Replacing a torn ligament inside the knee with a tendon graft.', why: 'For an unstable knee after a sports injury.', steps: ['Keyhole surgery under anaesthesia.', 'A tendon is taken from the knee or hamstring.', 'Tunnels are drilled in the bones.', 'The graft is pulled through and fixed.'], rec: 'Nine to 12 months of rehab before full sport.', risk: 'Stiffness, the graft tearing, infection.', then: 'Hey Groves used a strip of thigh tissue in 1917.', f: 'Female athletes tear their ACL more often than males in many sports.', p: ['knee', { scope: 1 }], x: ['arthroscopy', 'knee-replacement'] },
    { id: 'arthroscopy', n: 'Arthroscopy (keyhole joint surgery)', c: 'bone', y: 1918, d: '1918', r: 'Tokyo, Japan', w: 'Kenji Takagi; Masaki Watanabe (1950s)', s: 'Looking inside a joint with a thin camera and repairing it through tiny cuts.', why: 'For torn cartilage, loose bits of bone and ligament problems.', steps: ['Anaesthesia.', 'Two or three small cuts are made.', 'The joint is filled with fluid and the camera inserted.', 'Small tools trim, repair or remove tissue.'], rec: 'Usually home the same day.', risk: 'Infection, stiffness, clots.', then: 'Takagi first used a cystoscope in a knee in 1918.', f: 'Trials showed that knee arthroscopy for arthritis usually does not help, so it is now used less for that.', p: ['knee', { scope: 1 }], x: ['acl-reconstruction', 'laparoscopy'] },
    { id: 'ilizarov', n: 'Ilizarov frame', c: 'bone', y: 1951, d: '1951', r: 'Kurgan, Soviet Union', w: 'Gavriil Ilizarov', s: 'A ring frame outside the leg, attached by wires through the bone, that can slowly lengthen or straighten bones.', why: 'For bones that will not heal, are crooked, or are too short.', steps: ['Wires or pins are passed through the bone.', 'They are attached to metal rings.', 'Rods between the rings are adjusted a tiny bit each day.', 'New bone grows in the gap.'], rec: 'The frame stays on for months.', risk: 'Pin infections, stiffness.', then: 'Ilizarov developed it in remote Siberia; it became famous after he treated Italian explorer Carlo Mauri in 1980.', f: 'Bone can be lengthened about 1 mm per day.', p: B('leg', 'implant', 'none'), x: ['fracture-plates'] },
    { id: 'hip-replacement', n: 'Hip replacement', c: 'bone', y: 1962, d: '1962', r: 'Wrightington, UK', w: 'John Charnley', s: 'Replacing a worn hip joint with a metal or ceramic ball and a plastic socket.', why: 'For hip arthritis causing severe pain and stiffness, or some hip fractures.', steps: ['Spinal or general anaesthesia.', 'The worn ball of the thigh bone is removed.', 'A stem with a new ball goes into the bone.', 'A new socket is fitted in the pelvis.'], rec: 'Walking the next day; most normal activities in about six weeks.', risk: 'Dislocation, infection, clots, wear over decades.', then: 'Charnley made low-friction joints and clean-air operating rooms to cut infections.', f: 'Called “the operation of the century” by The Lancet.', p: ['hip', { implant: 1 }], x: ['knee-replacement'] },
    { id: 'scoliosis', n: 'Scoliosis surgery', c: 'bone', y: 1962, d: '1962', r: 'Houston, USA', w: 'Paul Harrington', s: 'Straightening a sideways-curved spine with rods and screws.', why: 'For large curves that keep getting worse, especially in teenagers.', steps: ['General anaesthesia; nerve monitoring.', 'Screws are put into the vertebrae.', 'Rods are attached and used to straighten the curve.', 'Bone graft fuses the spine.'], rec: 'About a week in hospital; back to school in weeks.', risk: 'Nerve injury, infection.', then: 'Harrington developed his rods for children paralysed by polio.', f: 'Patients can grow a few centimetres taller straight after surgery.', p: ['spine', { rods: 1 }], x: ['spinal-fusion'] },
    { id: 'knee-replacement', n: 'Knee replacement', c: 'bone', y: 1968, d: '1968', r: 'Canada and USA', w: 'Frank Gunston; John Insall (1970s)', s: 'Capping the worn ends of the thigh and shin bones with metal and plastic.', why: 'For severe knee arthritis.', steps: ['Spinal or general anaesthesia.', 'Worn bone surfaces are trimmed.', 'Metal parts are fixed to the bones.', 'A plastic insert acts as cartilage.'], rec: 'Walking within a day; full recovery takes months.', risk: 'Stiffness, infection, clots.', then: 'Over a million are done each year worldwide.', f: 'Robots now help some surgeons make precise cuts.', p: ['knee', { implant: 1 }], x: ['hip-replacement', 'arthroscopy'] },
    // ---------------- transplants
    { id: 'kidney-transplant', n: 'Kidney transplant', c: 'transplant', y: 1954, d: '1954', r: 'Boston, USA', w: 'Joseph Murray (patient Richard Herrick, donor his twin Ronald)', s: 'Placing a healthy kidney from a donor into a person whose kidneys have failed.', why: 'Kidney failure, instead of lifelong dialysis.', steps: ['The donor kidney is removed (from a living or deceased donor).', 'It is placed low in the belly.', 'Its vessels are joined to the leg vessels.', 'Its ureter is joined to the bladder.'], rec: 'About a week in hospital; anti-rejection medicine for life.', risk: 'Rejection, infection.', then: 'Using identical twins avoided rejection. Murray won the Nobel Prize in 1990.', f: 'The old kidneys are usually left in place.', p: B('kidney', 'stitch', 'open'), x: ['anti-rejection', 'nephrectomy', 'liver-transplant'] },
    { id: 'bone-marrow-transplant', n: 'Bone marrow transplant', c: 'transplant', y: 1956, d: '1956', r: 'Cooperstown and Seattle, USA', w: 'E. Donnall Thomas', s: 'Replacing diseased blood-making cells with healthy stem cells from a donor or the patient.', why: 'For leukaemia, lymphoma and some blood and immune diseases.', steps: ['Chemotherapy or radiation destroys the diseased marrow.', 'Donor stem cells are collected from blood or marrow.', 'They are given like a blood transfusion.', 'They find their way to the bones and start making blood.'], rec: 'Weeks in hospital until blood counts recover.', risk: 'Infection, graft-versus-host disease.', then: 'Thomas’s first success was between twins; Robert Good did the first matched non-twin transplant in 1968.', f: 'Donor registries match strangers across the world.', p: ['med', { i: 'cell' }], x: ['blood-transfusion', 'kidney-transplant'] },
    { id: 'anti-rejection', n: 'Anti-rejection medicines', c: 'transplant', y: 1983, d: '1960s; ciclosporin 1983', r: 'UK, Switzerland, USA', w: 'Roy Calne; Jean-François Borel', s: 'Drugs that calm the immune system so it does not attack a transplanted organ.', why: 'Without them, the body rejects any organ that is not from an identical twin.', then: 'Azathioprine (1962) allowed early transplants; ciclosporin, from a soil fungus found in Norway, made them routine.', f: 'Borel’s fungus came from a soil sample collected on holiday.', p: ['med', { i: 'pill', color: '#2e7d32' }], x: ['kidney-transplant', 'heart-transplant'] },
    { id: 'liver-transplant', n: 'Liver transplant', c: 'transplant', y: 1963, d: '1963 (first); 1967 (first success)', r: 'Denver, USA', w: 'Thomas Starzl', s: 'Replacing a failing liver with a whole or partial liver from a donor.', why: 'Liver failure, some liver cancers and children’s liver diseases.', steps: ['The diseased liver is removed.', 'The donor liver is connected to the main blood vessels.', 'The bile duct is joined.', 'Intensive care follows.'], rec: 'Two to three weeks in hospital.', risk: 'Rejection, bleeding, infection.', then: 'Starzl’s first patients did not survive; by 1967 a child lived over a year.', f: 'A living donor can give part of their liver — both parts grow back to full size.', p: B('liver', 'stitch', 'open'), x: ['kidney-transplant', 'anti-rejection'] },
    { id: 'pancreas-transplant', n: 'Pancreas transplant', c: 'transplant', y: 1966, d: '1966', r: 'Minneapolis, USA', w: 'William Kelly and Richard Lillehei', s: 'Giving a person with type 1 diabetes a pancreas that makes insulin.', why: 'For type 1 diabetes, often together with a kidney transplant.', steps: ['The donor pancreas is placed in the lower belly.', 'Its vessels are joined to the leg vessels.', 'Its juices drain into the bowel.', 'Insulin injections often stop at once.'], rec: 'About a week in hospital.', risk: 'Rejection, clots, infection.', then: 'Transplanting only the insulin-making islet cells began in 2000 (Edmonton protocol).', f: 'Many patients stop needing insulin straight after surgery.', p: B('pancreas', 'stitch', 'open'), x: ['kidney-transplant', ['medicine-atlas.html#insulin', 'Insulin']] },
    { id: 'heart-transplant', n: 'Heart transplant', c: 'transplant', y: 1967, d: '1967', r: 'Cape Town, South Africa', w: 'Christiaan Barnard (patient Louis Washkansky)', s: 'Replacing a failing heart with a donor heart.', why: 'End-stage heart failure.', steps: ['The patient is put on a heart-lung machine.', 'The diseased heart is removed.', 'The donor heart is stitched to the blood vessels.', 'It is restarted.'], rec: 'Two to three weeks in hospital; about half of patients live 12 years or more.', risk: 'Rejection, infection, narrowed arteries later.', then: 'Washkansky lived 18 days. Results improved hugely with ciclosporin in the 1980s.', f: 'The donor heart has no nerve connections, so it speeds up more slowly with exercise.', p: ['heart'], x: ['heart-lung-machine', 'artificial-heart', 'anti-rejection'] },
    { id: 'lung-transplant', n: 'Lung transplant', c: 'transplant', y: 1983, d: '1983 (first long-term success)', r: 'Toronto, Canada', w: 'Joel Cooper; first attempt by James Hardy (1963)', s: 'Replacing one or both diseased lungs with donor lungs.', why: 'Cystic fibrosis, emphysema, lung fibrosis.', steps: ['One or both lungs are removed.', 'Donor lungs are joined at the airways and blood vessels.', 'The patient is ventilated in intensive care.', 'Physiotherapy starts early.'], rec: 'Weeks in hospital; lifelong medicines.', risk: 'Rejection, infection.', then: 'Cooper’s patient Tom Hall lived over six years.', f: 'Donor lungs can be “reconditioned” in a machine outside the body before transplant.', p: ['lung'], x: ['heart-transplant'] },
    { id: 'hand-transplant', n: 'Hand transplant', c: 'transplant', y: 1998, d: '1998', r: 'Lyon, France', w: 'Jean-Michel Dubernard and team', s: 'Attaching a donor hand: bone, tendons, nerves, vessels and skin.', why: 'For people who have lost a hand.', steps: ['Bones are joined with plates.', 'Tendons, arteries and veins are joined.', 'Nerves are repaired under a microscope.', 'Skin is closed.'], rec: 'Years of therapy as nerves regrow.', risk: 'Rejection, infection, side effects of drugs.', then: 'The first patient later asked for it to be removed; later patients have done better.', f: 'Feeling slowly returns as nerves grow about 1 mm a day.', p: ['hand', { micro: 1 }], x: ['replantation', 'face-transplant'] },
    { id: 'face-transplant', n: 'Face transplant', c: 'transplant', y: 2005, d: '2005', r: 'Amiens, France', w: 'Bernard Devauchelle and Jean-Michel Dubernard (patient Isabelle Dinoire)', s: 'Transplanting facial tissue from a donor to someone with severe facial injuries.', why: 'For people unable to eat, speak or show expressions after injury or disease.', steps: ['Donor face tissue is removed with its vessels and nerves.', 'It is attached under a microscope.', 'Muscles and nerves are connected.', 'Lifelong anti-rejection medicine follows.'], rec: 'Months to years of therapy.', risk: 'Rejection, infection, psychological challenges.', then: 'The face looks like neither the donor nor the recipient, but a mix.', f: 'About 50 face transplants have been done worldwide.', p: B('face', 'microscope', 'open'), x: ['hand-transplant', 'gillies'] },
    { id: 'uterus-transplant', n: 'Womb transplant', c: 'transplant', y: 2014, d: '2014 (first birth)', r: 'Gothenburg, Sweden', w: 'Mats Brännström', s: 'Transplanting a womb so a woman born without one, or who lost hers, can carry a pregnancy.', why: 'For uterine factor infertility.', steps: ['A womb is removed from a living or deceased donor.', 'It is connected to the recipient’s blood vessels.', 'IVF embryos are transferred later.', 'The womb is usually removed after one or two births.'], rec: 'Anti-rejection drugs until the womb is removed.', risk: 'Rejection, surgical risks for donor and recipient.', then: 'The first baby, born in 2014, was carried in a womb donated by a family friend.', f: 'Babies born this way are delivered by caesarean section.', p: B('uterus', 'stitch', 'open'), x: ['ivf-retrieval'] },
    { id: 'xenotransplant', n: 'Animal-to-human transplants', c: 'transplant', y: 2022, d: '2022', r: 'Maryland, USA', w: 'Bartley Griffith and Muhammad Mohiuddin', s: 'Transplanting gene-edited pig organs into people, to ease the shortage of human donors.', why: 'Thousands of people die each year waiting for organs.', then: 'David Bennett lived two months with a pig heart in 2022. Pig kidney transplants began in 2024.', f: 'The pigs are gene-edited so the human body is less likely to reject their organs.', p: ['heart'], x: ['heart-transplant', 'kidney-transplant'] },
    // ---------------- plastic
    { id: 'rhinoplasty-sushruta', n: 'Nose reconstruction (Indian method)', c: 'plastic', y: -600, d: 'c. 6th century BCE', r: 'Ancient India', w: 'Described by Sushruta', s: 'Rebuilding a nose with a flap of skin turned down from the forehead or cheek.', why: 'Noses were cut off as a punishment in ancient India.', steps: ['A leaf was cut to the shape of the missing nose.', 'A flap of skin of that shape was cut from the cheek or forehead, still attached at one end.', 'It was twisted down over the nose.', 'Reeds kept the nostrils open while it healed.'], then: 'British surgeons saw it done in India in 1794 and brought the method to Europe. The forehead flap is still used.', f: 'It is one of the oldest plastic surgery techniques still in use.', p: B('nose', 'scalpel', 'open'), x: ['tagliacozzi', 'sushruta-samhita'] },
    { id: 'cleft-lip', n: 'Cleft lip and palate repair', c: 'plastic', y: 390, d: '390 CE (first record, China)', r: 'China, later worldwide', w: 'Unknown Chinese surgeon; modern repair by Ralph Millard (1955)', s: 'Closing a gap in the upper lip or roof of the mouth that a baby is born with.', why: 'To help with feeding, speech, hearing and appearance.', steps: ['The lip is usually repaired at about three months.', 'The edges are carefully cut and rotated.', 'Muscle and skin are joined in layers.', 'The palate is repaired at about one year.'], rec: 'A few days in hospital; speech therapy later.', risk: 'Scarring, needing more surgery as the child grows.', then: 'A Chinese record tells of a young man, Wei Yang-chi, whose cleft lip was repaired in 390.', f: 'Charities such as Smile Train and Operation Smile have funded millions of repairs.', p: B('face', 'stitch', 'none'), x: ['rhinoplasty-sushruta'] },
    { id: 'tagliacozzi', n: 'Italian arm-flap nose', c: 'plastic', y: 1597, d: '1597', r: 'Bologna, Italy', w: 'Gaspare Tagliacozzi', s: 'Rebuilding a nose with skin from the upper arm, with the arm strapped to the head for weeks.', why: 'Noses were lost in sword fights and to syphilis.', steps: ['A flap of skin was raised on the upper arm, still attached.', 'The arm was strapped to the head.', 'The flap grew onto the nose.', 'After about three weeks, it was cut free and shaped.'], then: 'Tagliacozzi’s book of 1597 is one of the first on plastic surgery.', f: 'His statue in Bologna’s anatomy theatre holds a nose.', p: B('nose', 'stitch', 'open'), x: ['rhinoplasty-sushruta', 'gillies'] },
    { id: 'skin-graft', n: 'Skin graft', c: 'plastic', y: 1869, d: '1869', r: 'Paris, France', w: 'Jacques-Louis Reverdin; Karl Thiersch (1874)', s: 'Moving thin layers of skin from one part of the body to cover a wound or burn.', why: 'For burns and wounds too large to close.', steps: ['A thin layer of skin is shaved from the thigh.', 'It may be meshed to stretch further.', 'It is laid on the clean wound.', 'A dressing holds it still while it takes.'], rec: 'The graft “takes” in about a week; the donor site heals like a graze.', risk: 'The graft failing, scarring, infection.', then: 'Reverdin used tiny pinch grafts; Thiersch used larger thin sheets.', f: 'Skin grown in the lab from a patient’s own cells is used for very large burns.', p: ['skinlayers'], x: ['burns-surgery', 'wound-debridement'] },
    { id: 'gillies', n: 'Facial reconstruction (Gillies)', c: 'plastic', y: 1917, d: '1917', r: 'Sidcup, UK', w: 'Harold Gillies', s: 'Rebuilding faces destroyed by war wounds using flaps, grafts and the “tubed pedicle”.', why: 'Thousands of WWI soldiers had terrible face injuries.', steps: ['Photographs and plaster casts planned each repair.', 'A strip of skin was rolled into a tube, still attached at both ends.', 'It was moved step by step to the face, keeping its blood supply.', 'Many operations followed over months or years.'], then: 'Gillies and his team treated over 5,000 men at Queen Mary’s Hospital. Artist Henry Tonks drew the patients.', f: 'Gillies is called the father of modern plastic surgery.', p: B('face', 'stitch', 'open'), x: ['burns-surgery', 'tagliacozzi', 'face-transplant'] },
    { id: 'burns-surgery', n: 'Burns surgery (Guinea Pig Club)', c: 'plastic', y: 1940, d: '1940s', r: 'East Grinstead, UK', w: 'Archibald McIndoe', s: 'Treating severe burns with saline baths, early grafting and rebuilding hands and faces.', why: 'WWII airmen were badly burned in plane fires.', steps: ['Dead tissue is removed early.', 'Skin grafts cover the wounds.', 'Hands are splinted to keep them working.', 'Faces and eyelids are rebuilt in stages.'], then: 'McIndoe’s patients formed the Guinea Pig Club and he insisted they mix with the town to rebuild their confidence.', f: 'East Grinstead became known as “the town that did not stare”.', p: ['skinlayers'], x: ['skin-graft', 'gillies'] },
    { id: 'replantation', n: 'Reattaching severed limbs', c: 'plastic', y: 1962, d: '1962', r: 'Boston, USA', w: 'Ronald Malt; thumb by Shigeo Komatsu and Susumu Tamai (1968)', s: 'Sewing back a cut-off arm, hand or finger by joining bone, tendons, vessels and nerves.', why: 'For traumatic amputations.', steps: ['The part is kept cool (not frozen) in a bag on ice.', 'Bone is shortened and fixed.', 'Arteries and veins are joined under a microscope.', 'Nerves and tendons are repaired.'], rec: 'Months of hand therapy.', risk: 'The part failing, stiffness, cold sensitivity.', then: 'Malt reattached the arm of 12-year-old Everett Knowles, injured by a train.', f: 'Blood vessels 1 mm wide are joined with thread thinner than a hair.', p: ['hand', { micro: 1 }], x: ['microsurgery', 'hand-transplant', 'amputation'] },
    { id: 'breast-implants', n: 'Breast implants and reconstruction', c: 'plastic', y: 1962, d: '1962', r: 'Houston, USA', w: 'Thomas Cronin and Frank Gerow', s: 'Silicone implants or the patient’s own tissue are used to rebuild a breast after cancer, or to change its size.', why: 'Reconstruction after mastectomy, or cosmetic reasons.', steps: ['An implant is placed under the skin or chest muscle.', 'Or skin and fat are moved from the belly with their vessels.', 'Vessels are joined under a microscope.', 'The nipple may be rebuilt later.'], rec: 'Weeks to months.', risk: 'Infection, scar tissue, implant problems; a rare lymphoma with some textured implants.', then: 'Timmie Jean Lindsey was the first woman to receive silicone implants, in 1962.', f: 'Using belly tissue (a DIEP flap) gives a breast that ages with the body.', p: B('breast', 'implant', 'open'), x: ['mastectomy', 'microsurgery'] },
    // ---------------- tech
    { id: 'laparoscopy', n: 'Laparoscopy (keyhole surgery)', c: 'tech', y: 1910, d: '1910', r: 'Stockholm, Sweden', w: 'Hans Christian Jacobaeus (after Georg Kelling, 1901)', s: 'Operating inside the belly through small cuts with a camera and long, thin instruments.', why: 'Less pain, smaller scars and faster recovery than large cuts.', steps: ['The belly is filled with carbon dioxide gas to make space.', 'A camera goes in through a small cut near the belly button.', 'Two or three more small cuts let instruments in.', 'The surgeon watches a screen.'], rec: 'Often home in a day.', risk: 'Injury to bowel or vessels, shoulder pain from the gas.', then: 'Kurt Semm did the first keyhole appendix removal in 1980 and was criticised; the 1985–87 gallbladder operations changed everything.', f: 'The pain in the shoulder afterwards comes from gas irritating the diaphragm.', p: B('belly', 'scope', 'keyhole'), x: ['cholecystectomy', 'appendectomy', 'robotic-surgery'] },
    { id: 'stereotactic-surgery', n: 'Stereotactic surgery', c: 'tech', y: 1947, d: '1947', r: 'Philadelphia, USA', w: 'Ernest Spiegel and Henry Wycis', s: 'A frame fixed to the head and maps of the brain guide a needle to an exact point in 3D.', why: 'To reach deep brain targets through a tiny hole.', steps: ['A frame or markers are fixed to the head.', 'A scan gives 3D coordinates of the target.', 'A needle is guided along a planned path.', 'The target is sampled, treated or stimulated.'], then: 'The idea led to deep brain stimulation and Gamma Knife radiosurgery.', f: 'Modern systems use cameras that track instruments like satellite navigation.', p: B('brain', 'needle', 'keyhole'), x: ['gamma-knife', 'deep-brain-stimulation'] },
    { id: 'flexible-endoscope', n: 'Flexible endoscope', c: 'tech', y: 1957, d: '1957', r: 'Michigan, USA', w: 'Basil Hirschowitz', s: 'A bendable tube of glass fibres carrying light and images, letting doctors look inside the stomach and bowel.', why: 'To diagnose and treat without cutting.', steps: ['The throat is numbed or sedation is given.', 'The scope is passed through the mouth.', 'Light and a camera show the inside.', 'Tools pass down a channel to take samples or treat.'], rec: 'Home the same day.', risk: 'Sore throat, rarely bleeding or a tear.', then: 'Hirschowitz tested the first fibre-optic scope on himself.', f: 'Today’s scopes have a tiny video camera chip at the tip.', p: B('stomach', 'scope', 'none'), x: ['colonoscopy', 'sinus-surgery'] },
    { id: 'microsurgery', n: 'Microsurgery', c: 'tech', y: 1960, d: '1960', r: 'Vermont, USA', w: 'Julius Jacobson and Ernesto Suarez', s: 'Operating under a microscope to join tiny blood vessels and nerves.', why: 'For reattaching fingers, moving tissue flaps, and eye, ear and brain surgery.', steps: ['A microscope magnifies the area 10–40 times.', 'Tiny instruments and fine thread are used.', 'Vessels are stitched around their edge.', 'Blood flow is checked.'], then: 'Operating microscopes were first used for ear surgery in 1921 by Carl-Olof Nylén.', f: 'The thread can be thinner than a human hair.', p: ['hand', { micro: 1 }], x: ['replantation', 'breast-implants'] },
    { id: 'laser-surgery', n: 'Laser surgery', c: 'tech', y: 1963, d: '1960s', r: 'USA', w: 'Leon Goldman and others', s: 'Using a focused beam of light to cut, seal or destroy tissue very precisely.', why: 'For eye problems, skin conditions, some tumours, kidney stones and more.', steps: ['The area is numbed or the patient anaesthetised.', 'The laser is aimed through a scope, fibre or microscope.', 'Light energy cuts or seals tissue.', 'Little bleeding occurs.'], then: 'The first laser was built in 1960; eye doctors used it to treat the retina within a few years.', f: 'Different colours of laser are absorbed by different tissues.', p: ['eye', { mode: 'laser' }], x: ['lasik', 'retina-repair', ['invention-atlas.html#laser', 'The laser']] },
    { id: 'gamma-knife', n: 'Gamma Knife radiosurgery', c: 'tech', y: 1968, d: '1968', r: 'Stockholm, Sweden', w: 'Lars Leksell', s: 'About 200 weak beams of radiation meet at one point in the brain to destroy a target — no cut at all.', why: 'For small brain tumours, blood vessel problems and some nerve pain.', steps: ['A frame or mask holds the head still.', 'Scans plan the target.', 'Many beams from different directions cross at the target.', 'Each beam alone is harmless to the tissue it passes.'], rec: 'Usually home the same day.', risk: 'Swelling, headache; effects build up over months.', then: 'It is called “surgery” though nothing is cut.', f: 'Beams are focused to less than a millimetre.', p: B('brain', 'laser', 'none'), x: ['stereotactic-surgery', 'brain-tumour'] },
    { id: 'robotic-surgery', n: 'Robotic surgery', c: 'tech', y: 2000, d: '2000', r: 'California, USA', w: 'Intuitive Surgical (da Vinci); first robot-assisted operation in 1985', s: 'The surgeon sits at a console and controls robotic arms that hold a 3D camera and tiny wristed instruments.', why: 'Steadier, more precise movements in tight spaces such as the pelvis.', steps: ['Small keyhole cuts are made.', 'The robot arms are docked and instruments inserted.', 'The surgeon operates from a console nearby.', 'Hand movements are scaled down and tremor filtered out.'], rec: 'Similar to keyhole surgery.', risk: 'Similar to keyhole surgery; longer set-up.', then: 'A PUMA 560 industrial robot guided a brain biopsy needle in 1985.', f: 'The robot does nothing by itself — every movement comes from the surgeon.', p: ['robotsurgery'], x: ['laparoscopy', 'telesurgery', 'prostatectomy'] },
    { id: 'telesurgery', n: 'Telesurgery (operating from far away)', c: 'tech', y: 2001, d: '2001', r: 'New York to Strasbourg', w: 'Jacques Marescaux', s: 'A surgeon in New York removed a gallbladder from a patient in France using a robot connected by a fibre-optic line.', why: 'One day it could bring expert surgery to remote places.', then: 'Called “Operation Lindbergh” after the first solo flight across the Atlantic.', f: 'The delay over 7,000 km was about 155 milliseconds.', p: ['robotsurgery'], x: ['robotic-surgery', 'cholecystectomy'] },
    { id: 'printed-implants', n: '3D-printed implants', c: 'tech', y: 2012, d: '2012', r: 'USA and the Netherlands', w: 'Glenn Green and Scott Hollister (airway splint); Bon Verweij (skull, 2014)', s: 'Implants and guides printed to fit one patient exactly, from a scan.', why: 'For unusual shapes, such as a skull defect or a baby’s collapsing windpipe.', steps: ['A CT scan makes a 3D model.', 'Engineers design an implant or cutting guide.', 'It is printed in plastic, titanium or a dissolving material.', 'The surgeon fits it during the operation.'], then: 'In 2012 baby Kaiba Gionfriddo got a printed splint for his windpipe that dissolved as he grew.', f: 'Surgeons also practise on printed copies of a patient’s organs before difficult operations.', p: ['skull', { modern: 1, hole: false }], x: ['robotic-surgery', ['invention-atlas.html#3d-printing', '3D printing']] }
  ];
})();
